import type { HandCat } from '../../pack';
import type { Raw } from '../types';

/** Il terzo blocco di bank/growth.ts in italiano, nello stesso ordine. */
export const GROWTH: Record<HandCat, Raw[]> = {
  history: [
    ['Pompei fu sepolta nel 79 d.C. Più o meno quando cominciarono gli scavi veri e propri?', 'Negli anni Quaranta del Settecento|Nel Trecento|Negli anni Novanta dell’Ottocento|Negli anni Sessanta del Novecento', 'Gli scavi iniziarono nel 1748. Più tardi, dai vuoti lasciati dai corpi nella cenere, si ricavarono i calchi in gesso delle vittime.'],
    ['Che cosa ricevevano come parte della paga gli operai che costruivano le piramidi egizie?', 'Birra|Monete d’oro|Seta|Spezie', 'Razioni di pane e birra, circa quattro o cinque litri al giorno. In Egitto le monete non esistevano ancora.'],
    ['Cleopatra regnava sull’Egitto, ma da dove veniva la sua famiglia?', 'Dalla Macedonia, in Grecia|Da Roma|Dalla Persia|Dalla Nubia', 'Era una Tolomea, di una dinastia greco-macedone, e fu la prima della famiglia a imparare l’egiziano.'],
    ['Quale imperatore romano avrebbe voluto nominare console il suo cavallo?', 'Caligola|Nerone|Augusto|Adriano', 'Gli autori antichi raccontano che il suo cavallo Incitato aveva una stalla di marmo e una mangiatoia d’avorio.'],
    ['Come facevano i romani un calcestruzzo che dura da 2.000 anni?', 'Con cenere vulcanica e calce|Solo con conchiglie tritate|Con albume d’uovo|Con limatura di ferro', 'I grumi di calce nell’impasto permettono al calcestruzzo romano di richiudere da solo le crepe quando ci entra l’acqua.'],
    ['Come gareggiavano gli atleti alle antiche Olimpiadi greche?', 'Nudi|In armatura completa|Con la maschera|Con lunghe tuniche', 'La parola «ginnasio» viene dal greco gymnós, che vuol dire nudo.'],
    ['Oltre che con le monete, con che cosa pagavano i vichinghi?', 'Con argento fatto a pezzi|Con perle d’ambra|Con panetti di sale|Con pesce secco', 'L’argento a pezzi: gioielli e monete tagliati in frammenti e pesati con piccole bilance pieghevoli.'],
    ['Chi furono i primi europei a raggiungere il Nord America?', 'I vichinghi|Gli spagnoli|I portoghesi|Gli inglesi', 'Leif Erikson sbarcò intorno all’anno 1000. Il loro accampamento a L’Anse aux Meadows, in Canada, è stato riportato alla luce.'],
    ['Nel Medioevo inglese, che cos’era un «trencher»?', 'Un piatto fatto di pane raffermo|Un fossato difensivo|La vanga di un soldato|Un coltello da tavola', 'Dopo il pasto, il pane inzuppato di sugo si mangiava o si dava ai poveri o ai cani. La parola è parente del nostro «tagliere».'],
    ['I cavalieri medievali avevano bisogno di una gru per salire a cavallo. Vero o falso?', 'Falso|Vero', 'È un mito. Un’armatura da battaglia pesava dai 15 ai 25 kg, distribuiti su tutto il corpo. Ci si poteva correre e perfino fare la ruota.'],
    ['Perché il viso della regina Elisabetta I era così bianco?', 'Il trucco era fatto con il piombo|Era sempre malata|I pittori lo schiarivano|Non usciva mai', 'La biacca veneziana, piombo bianco mescolato con aceto, avvelenava lentamente molte delle persone che la usavano.'],
    ['Nel Seicento, come venivano soprannominati i caffè di Londra?', 'Università da un penny|Banche dei chicchi|Stanze della chiacchiera|Templi neri', 'Con un penny avevi un caffè e potevi unirti ai dibattiti su scienza, politica e notizie.'],
    ['Che cosa fece Isaac Newton quando la peste fece chiudere Cambridge nel 1665?', 'Lavorò da casa sulla gravità e sul calcolo|Salpò per l’America|Si arruolò|Studiò da medico', 'Tornò nella sua fattoria di Woolsthorpe e più tardi definì quegli anni i più produttivi della sua vita.'],
    ['La spedizione di Magellano fu la prima a fare il giro del mondo. Magellano lo completò?', 'No, fu ucciso durante il viaggio|Sì|Sì, due volte|Fece l’ultimo tratto a nuoto', 'Morì nelle Filippine nel 1521. Nel 1522 tornarono a casa una nave su cinque e 18 uomini su circa 270, tra cui il vicentino Antonio Pigafetta, che raccontò il viaggio.'],
    ['Nel 1492, dove pensava di essere sbarcato Cristoforo Colombo?', 'Vicino all’Asia|In Africa|Su un nuovo continente|In Australia', 'Fino alla morte sostenne di aver trovato isole al largo dell’Asia: ecco perché gli abitanti furono chiamati «indiani».'],
    ['Come tenevano i registri gli inca senza la scrittura?', 'Con cordicelle annodate|Con tavolette d’argilla|Con sassolini dipinti|Con corteccia incisa', 'Si chiamavano quipu: con colori, nodi e posizioni registravano numeri, tasse e forse anche storie.'],
    ['Dove fu costruita Tenochtitlán, la capitale azteca?', 'Su un’isola in mezzo a un lago|In cima a una montagna|In un deserto|Dentro il cratere di un vulcano', 'Oggi lì sorge Città del Messico, che sta ancora sprofondando lentamente nel vecchio fondale del lago.'],
    ['Che cosa è arrivato prima in Europa?', 'Gli occhiali|La stampa a caratteri mobili', 'Gli occhiali comparvero in Italia intorno al 1290, circa 150 anni prima della stampa di Gutenberg.'],
    ['Che cosa fecero i londinesi sul Tamigi ghiacciato nell’inverno tra il 1683 e il 1684?', 'Una fiera con negozi e giochi|Un castello di ghiaccio|Corse di renne|Niente: era vietato salirci', 'La Grande fiera del gelo aveva bancarelle, torchi da stampa, corse di cavalli e spettacoli di burattini, tutto sul ghiaccio.'],
    ['Nel 1752, quali giorni saltò la Gran Bretagna?', 'Undici giorni di settembre|Tutto febbraio|Il giorno di Capodanno|Una settimana d’estate', 'Con il cambio di calendario, a mercoledì 2 settembre seguì giovedì 14 settembre. L’Italia aveva fatto lo stesso salto già nel 1582.'],
    ['Quale presidente degli Stati Uniti ebbe una licenza per vendere alcolici?', 'Abraham Lincoln|George Washington|Theodore Roosevelt|John Adams', 'Nel 1833 l’emporio di Lincoln a New Salem, nell’Illinois, aveva la licenza per gli alcolici.'],
    ['George Washington aveva denti notoriamente pessimi. Di che cosa era fatta la sua dentiera?', 'Avorio, metallo e veri denti umani|Legno|Vetro|Pietra', 'La storia dei denti di legno è un mito. Alcune sue dentiere usavano denti presi ad altre persone.'],
    ['Nel 1859 un’enorme tempesta solare fece fare che cosa ai fili del telegrafo?', 'Fare scintille, e funzionare con le batterie staccate|Fondere all’istante|Suonare musica|Tacere per sempre', 'L’evento di Carrington diede fuoco alla carta dei telegrafi, e si videro aurore fino ai Caraibi.'],
    ['Che cosa avrebbe fatto la banda del Titanic mentre la nave affondava?', 'Continuò a suonare|Saltò giù per prima|Suonò la sirena della nave|Si nascose in cucina', 'I sopravvissuti raccontarono che suonavano per calmare i passeggeri. Nessuno degli otto musicisti si salvò.'],
    ['La prima multa per eccesso di velocità a un’auto, nel 1896, fu data a chi andava più o meno a quanto?', '13 km/h|60 km/h|35 km/h|100 km/h', 'Walter Arnold andava a 13 km/h dove il limite era 3, nel Kent. Lo inseguì un poliziotto in bicicletta.'],
    ['Secondo una legge britannica del 1865, le auto dovevano avere davanti che cosa?', 'Una persona a piedi con una bandiera rossa|Un cavallo|Un uomo con una campanella|Un cane', 'Il Red Flag Act limitava anche la velocità a circa 6 km/h in campagna. Fu abolito nel 1896.'],
    ['Nella Londra dell’Ottocento, chi erano i «mudlarks», le «allodole del fango»?', 'Chi frugava nel fango del fiume cercando cose da vendere|Un tipo di uccello|Spazzini|Costruttori di barche', 'Soprattutto bambini poveri, che con la bassa marea raccoglievano carbone, corde e chiodi dal Tamigi.'],
    ['Perché nelle foto dell’Ottocento si vede così poca gente sorridere?', 'Pose lunghissime, e in un ritratto sorridere era sciocco|Sorridere era vietato|Le macchine non mostravano i denti|Tutti avevano mal di denti', 'Un sorriso è difficile da tenere per molti secondi, e un ritratto era una cosa seria, da fare una volta nella vita.'],
    ['Fino al 1970, i marinai della marina britannica ricevevano ogni giorno una razione di che cosa?', 'Rum|Birra|Limonata|Whisky', 'L’ultima fu versata il 31 luglio 1970, giorno che i marinai chiamano ancora Black Tot Day.'],
    ['Perché i marinai britannici erano soprannominati «limeys»?', 'Bevevano succo di lime contro lo scorbuto|Adoravano la torta al lime|Le loro navi erano verdi|Venivano da Limehouse', 'Il succo di agrumi preveniva lo scorbuto, una malattia mortale dovuta alla mancanza di vitamina C.'],
    ['Che cosa teneva Gustave Eiffel in cima alla sua torre?', 'Un appartamento privato|Un cannone|La lampada di un faro|Una campana', 'Nel 1889 ci ricevette Thomas Edison.'],
    ['Chi progettò lo scheletro di ferro dentro la Statua della Libertà?', 'Gustave Eiffel|Leonardo da Vinci|Thomas Edison|Antoni Gaudí', 'Il suo scheletro di ferro permette al sottile rivestimento di rame di flettersi al vento.'],
    ['Quale hostess era a bordo dell’Olympic, del Titanic e del Britannic quando ciascuna ebbe il suo disastro?', 'Violet Jessop|Molly Brown|Florence Nightingale|Lucy Duff Gordon', 'Sopravvisse alla collisione dell’Olympic, al naufragio del Titanic e al Britannic che urtò una mina.'],
    ['Che cosa successe nella «tregua di Natale» del 1914?', 'I nemici si incontrarono nella terra di nessuno|Fu firmato un trattato di pace|Ci fu un matrimonio reale|Furono vietati i canti di Natale', 'In alcuni tratti del fronte occidentale i nemici si scambiarono regali, cantarono e giocarono perfino a calcio.'],
    ['Quale esercito arruolò ufficialmente un orso nella Seconda guerra mondiale?', 'Quello polacco|Quello russo|Quello canadese|Quello finlandese', 'Wojtek, un orso bruno siriano, trasportava proiettili d’artiglieria per le truppe polacche in Italia, anche a Montecassino, ed ebbe un grado.'],
    ['Come fece l’Operazione Mincemeat a ingannare i nazisti nel 1943?', 'Un cadavere portava falsi piani d’invasione|Un esercito di palloncini|Uno sceneggiato radiofonico|Un cane doppiogiochista', 'Il corpo, vestito da ufficiale, arrivò a riva in Spagna, e la Germania spostò truppe lontano dalla Sicilia.'],
    ['Nella Seconda guerra mondiale gli Alleati usarono un esercito di finti che cosa per ingannare le spie?', 'Carri armati gonfiabili|Soldati di cartone|Corazzate di legno|Aerei di carta', 'L’«Esercito fantasma» usava carri armati di gomma, effetti sonori registrati e false comunicazioni radio.'],
    ['Che cosa è venuto prima?', 'Il primo volo dei fratelli Wright|La fine dell’Impero ottomano', 'L’aereo volò nel 1903. Il sultanato ottomano fu abolito nel 1922.'],
    ['Che cosa è venuto prima?', 'La locomotiva a vapore|La bicicletta', 'La locomotiva di Trevithick viaggiò nel 1804. La prima «macchina da corsa» a due ruote arrivò nel 1817, senza pedali.'],
    ['Che cosa è venuto prima?', 'La prima fotografia|Il primo programma per computer', 'Niépce scattò la sua foto intorno al 1826. Ada Lovelace pubblicò il suo programma nel 1843.'],
    ['Che cosa è venuto prima?', 'La tavoletta di cioccolato|Il cono gelato', 'La Fry’s di Bristol fece la prima tavoletta di cioccolato nel 1847. I coni si diffusero intorno al 1904.'],
    ['Perché i giudici britannici portano la parrucca?', 'È una moda del Seicento che è rimasta|Per nascondere chi sono|Per le leggi sui pidocchi|Per sembrare più vecchi', 'Le parrucche erano di moda sotto re Carlo II, e i tribunali le hanno tenute molto dopo che tutti le avevano abbandonate.'],
    ['Perché alcune vecchie case britanniche hanno finestre murate?', 'C’era una tassa sulle finestre|Per gli oscuramenti di guerra|Per moda|Non c’era vetro', 'Dal 1696 al 1851 la Gran Bretagna tassò le finestre, e la gente ne murava qualcuna per pagare meno.'],
    ['Che cos’è Ötzi, trovato sulle Alpi nel 1991?', 'Un uomo congelato da circa 5.300 anni|Un soldato romano|Un mammut|Un monaco medievale', 'Lo trovarono due escursionisti in un ghiacciaio. Ha 61 tatuaggi e una punta di freccia nella spalla. Oggi riposa nel museo di Bolzano.'],
    ['Gli strumenti musicali più antichi che si conoscano sono flauti fatti di che cosa?', 'Osso d’uccello e avorio di mammut|Legno|Argilla|Rame', 'I flauti trovati in alcune grotte della Germania hanno circa 40.000 anni.'],
    ['Quanti anni hanno le pitture rupestri più antiche che si conoscano?', 'Più di 45.000|Circa 5.000|Circa 2.000|Circa 10.000', 'Il dipinto di un maiale selvatico a Sulawesi, in Indonesia, ha almeno 45.500 anni.'],
    ['Di chi era l’abitudine di contare per 60 che ci ha dato i 60 minuti e i 360 gradi?', 'Dei babilonesi|Dei romani|Dei greci|Dei maya', 'La loro matematica in base 60 si divide alla perfezione per 2, 3, 4, 5, 6, 10, 12, 15, 20 e 30.'],
    ['Il vecchio ufficio postale di New York porta un motto sui corrieri che sfidano neve e pioggia. Di quali messaggeri si parlava in origine?', 'Di quelli degli antichi persiani|Di quelli dei romani|Di quelli del Pony Express|Di quelli dei mongoli', 'Lo storico greco Erodoto descrisse i cavalieri a staffetta persiani, che niente poteva fermare.'],
    ['Quanto durò il servizio postale del Pony Express?', 'Circa 18 mesi|Circa 18 anni|Circa 5 anni|Circa 50 anni', 'Funzionò dal 1860 al 1861. Il telegrafo lo mise fuori gioco quasi da un giorno all’altro.'],
    ['Quando nel 2022 fu ritrovata a 3.000 m di profondità la nave Endurance di Shackleton, in che stato era?', 'Incredibilmente intera, con il nome ancora leggibile|Ridotta in polvere|Congelata dentro un iceberg|Arenata su una spiaggia', 'Era affondata nel mare di Weddell nel 1915. In quell’acqua fredda e buia non ci sono vermi che mangiano il legno.'],
    ['La «Rivoluzione d’ottobre» russa del 1917 avvenne in quale mese secondo il calendario di oggi?', 'Novembre|Ottobre|Settembre|Dicembre', 'La Russia usava ancora il vecchio calendario giuliano, indietro di 13 giorni.'],
    ['Quanto durò l’Impero romano d’Oriente dopo la caduta di quello d’Occidente nel 476?', 'Circa 1.000 anni|Circa 100 anni|Circa 50 anni|Circa 3.000 anni', 'Andò avanti fino a quando gli ottomani presero Costantinopoli, nel 1453.'],
    ['I romani facevano bollire il succo d’uva in pentole di piombo per ottenere che cosa?', 'Uno sciroppo dolce|Vernice|Colla|Un collirio', 'La sapa era piena di piombo e finiva nel vino e nei cibi.'],
    ['Quale popolo antico mummificò gatti a centinaia di migliaia?', 'Gli egizi|I greci|Gli aztechi|I celti', 'I gatti erano sacri alla dea Bastet. Nel 1890, in Inghilterra, un intero carico di mummie di gatto fu macinato per farne concime.'],
    ['Quale paese ha, secondo molti, la più antica università ancora attiva?', 'Il Marocco|L’Italia|L’Inghilterra|L’Egitto', 'L’università al-Qarawiyyin di Fez fu fondata nell’859 da una donna, Fatima al-Fihri. Bologna arrivò nel 1088.'],
    ['Su che cosa appoggiavano spesso la testa di notte gli antichi egizi?', 'Su poggiatesta di legno o di pietra|Su cuscini di piume|Su sacchi di paglia|Su cuscini di seta', 'I poggiatesta ricurvi tenevano la testa sollevata dal pavimento.'],
    ['Da dove si vedono meglio le linee di Nazca, in Perù?', 'Dall’alto, in volo|Da una barca|Da sottoterra|Da una torre alta', 'Figure giganti, da un colibrì a una scimmia, furono tracciate nel deserto circa 2.000 anni fa.'],
    ['Perché la torre di Pisa pendeva già mentre la costruivano?', 'Per il terreno cedevole sotto un lato|Per un terremoto|Era progettata per pendere|Per i danni di una guerra', 'Cominciò a sprofondare quando fu alzato il secondo piano, nel 1178, e i lavori durarono quasi 200 anni.'],
    ['Tra il 1990 e il 2001, gli ingegneri raddrizzarono la torre di Pisa più o meno di quanto?', '45 cm|Del tutto|5 metri|Per niente', 'Tolsero con delicatezza un po’ di terra da sotto il lato più alto. Pende ancora di circa 4 gradi.'],
    ['Che cos’è, a rigore, il «Big Ben»?', 'La grande campana|La torre dell’orologio|Il quadrante|Il palazzo del Parlamento', 'Nel 2012 la torre è stata chiamata Elizabeth Tower. Il Big Ben è la campana di 13,7 tonnellate che c’è dentro.'],
    ['Nel 1974, alcuni contadini cinesi che scavavano un pozzo trovarono che cosa?', 'L’esercito di terracotta|Un nido di uova di dinosauro|Una miniera d’oro|Un’antica barca', 'Circa 8.000 soldati d’argilla a grandezza naturale fanno la guardia alla tomba del primo imperatore cinese, ognuno con un volto diverso.'],
    ['Chi trovò i rotoli del Mar Morto?', 'Un pastore che cercava una capra smarrita|Un archeologo|Un turista|Un soldato', 'Nel 1946–47 un giovane beduino lanciò un sasso in una grotta vicino a Qumran e sentì rompersi una giara.'],
    ['Chi scrisse la Storia di Genji, spesso definita il primo romanzo del mondo?', 'Una nobildonna giapponese|Un monaco cinese|Un cavaliere inglese|Un poeta persiano', 'Murasaki Shikibu la scrisse intorno all’anno 1010, quando era al servizio della corte imperiale.'],
    ['Che aspetto avevano le piramidi di Giza quando erano nuove?', 'Lisce e di un bianco brillante|Dipinte di rosso|Ricoperte d’oro|Verdi di muschio', 'Le rivestiva calcare levigato. Gran parte fu poi portato via per costruire il Cairo.'],
    ['Più o meno quanto tempo ci volle per costruire la Grande Piramide?', 'Circa 20 anni|Circa 200 anni|Circa 2 anni|Circa 2.000 anni', 'Migliaia di operai pagati, non schiavi, trascinarono circa 2,3 milioni di blocchi.'],
    ['Angkor Wat, in Cambogia, fu costruito all’inizio come tempio di quale religione?', 'Induismo|Buddhismo|Islam|Cristianesimo', 'Nel XII secolo fu dedicato al dio Vishnu, e più tardi diventò buddhista.'],
    ['Che cosa successe nell’«evento di Tunguska» del 1908?', 'Un sasso spaziale esplose sopra la Siberia|Eruttò un vulcano|Sparì una città|Una cometa cadde in mare', 'Abbatté circa 80 milioni di alberi su 2.000 km², senza lasciare un cratere.'],
    ['Quale vulcano causò l’«anno senza estate» del 1816?', 'Il Tambora|Il Vesuvio|Il Krakatoa|L’Etna', 'La sua cenere raffreddò il pianeta. Chiusa in casa in quell’estate piovosa, Mary Shelley cominciò Frankenstein.'],
    ['Quando il Krakatoa eruttò nel 1883, fin dove si sentì il boato?', 'A circa 4.800 km|A circa 50 km|A circa 500 km|A circa 20.000 km', 'Sull’isola di Rodrigues, vicino a Mauritius, quattro ore dopo: il suono più forte della storia documentata.'],
    ['Qual è il nome completo della Statua della Libertà?', 'La Libertà che illumina il mondo|La Signora Libertà di New York|La Fiaccola della Libertà|La Statua della Repubblica', 'Fu un regalo della Francia per il centenario degli Stati Uniti, nel 1876, ma fu finita con dieci anni di ritardo.'],
    ['Che cosa significa «Bucefalo», il nome del cavallo di Alessandro Magno?', 'Testa di bue|Vento veloce|Stella nera|Cuor di leone', 'Alessandro lo domò da ragazzo e, quando morì, gli dedicò una città.'],
    ['Chi tenne per un po’ la Gioconda in camera da letto?', 'Napoleone|Luigi XIV|La regina Vittoria|Abraham Lincoln', 'La prese dal Louvre intorno al 1800. Tornò al museo quando lui diventò imperatore.'],
    ['L’influenza «spagnola» del 1918 non era partita dalla Spagna. Perché si chiama così?', 'I giornali spagnoli ne parlavano apertamente|Il re di Spagna fu il primo ad ammalarsi|La diffusero le navi spagnole|La battezzò un medico spagnolo', 'Altrove la censura di guerra la nascondeva; la Spagna, neutrale, ne parlava liberamente, così sembrò che venisse da lì.'],
    ['Gli antichi romani avevano una dea di che cosa?', 'Delle fogne|Dei calzini|Degli starnuti|Dei cucchiai', 'Cloacina proteggeva la Cloaca Massima, la grande fogna di Roma, che in alcuni tratti porta ancora acqua oggi.'],
    ['Quando ha eseguito la Francia la sua ultima condanna a morte con la ghigliottina?', 'Nel 1977|Nel 1880|Nel 1920|Nel 1945', 'Hamida Djandoubi fu giustiziato a Marsiglia nel settembre 1977, pochi mesi dopo l’uscita di Guerre stellari.'],
    ['Nel 1919, un’ondata di che cosa uccise 21 persone a Boston?', 'Melassa|Birra|Latte|Petrolio', 'Si squarciò un serbatoio gigante, e un’onda di sciroppo alta diversi metri travolse le strade.'],
    ['Più o meno per quanto tempo Luigi XIX fu re di Francia?', 'Circa 20 minuti|Circa 20 giorni|Circa 2 anni|Circa 20 anni', 'Nel 1830 suo padre abdicò, e Luigi firmò la propria abdicazione subito dopo.'],
    ['Chi fu la prima persona a superare le cascate del Niagara dentro un barile e a sopravvivere?', 'Una maestra di 63 anni|Un forzuto del circo|Un ragazzino|Un pompiere', 'Annie Edson Taylor lo fece nel 1901, il giorno del suo compleanno, sperando di arricchirsi. Prima, per prova, ci mandò il suo gatto.'],
    ['Che cosa tenne Mary Shelley nella sua scrivania per quasi 30 anni?', 'Il cuore del marito morto|Il violino del marito|Una ciocca di capelli di Lord Byron|Un uccello morto', 'Quando Percy Shelley fu cremato su una spiaggia, a Viareggio, nel 1822, il cuore non bruciò. Fu trovato tra le cose di lei dopo la sua morte.'],
    ['In alcune foto di neonati dell’Ottocento, la madre si nasconde sotto un telo. Perché?', 'Per tenere fermo il bambino durante la lunga posa|Le madri non potevano stare nelle foto|Per portare fortuna|Per fare ombra', 'Posava da «poltrona» drappeggiata. Alcuni fotografi la tagliavano via, altri non se ne preoccupavano.'],
    ['Come morì nel 1567 Hans Steininger, famoso per la sua barba di 1,4 m?', 'Ci inciampò sopra|Prese fuoco|Rimase incastrata in una porta|Se la mangiò una capra', 'Scappando da un incendio, dimenticò di arrotolarla. La barba è conservata in un museo di Braunau, in Austria.'],
    ['Che cosa facevano per divertimento alcuni ricchi vittoriani alle feste?', 'Sbendavano mummie egizie|Corse di tartarughe|Mangiavano foglia d’oro|Scherma bendati', 'Nell’Ottocento lo «sbendaggio» delle mummie attirava pubblico pagante, a volte con conferenza e rinfresco.'],
    ['Che cosa avrebbe proibito di mangiare Pitagora ai suoi seguaci?', 'Le fave|Il pane|Il pesce|Le olive', 'Una leggenda dice che preferì morire piuttosto che scappare attraversando un campo di fave.'],
    ['Che fine fece il cervello di Albert Einstein dopo la sua morte nel 1955?', 'Un patologo se lo portò a casa|Fu sepolto con lui|Fu congelato|Einstein lo lasciò a un’università', 'Thomas Harvey lo tenne per decenni, per un periodo in barattoli dentro una cassa di sidro.'],
    ['Di che cosa si lamentava un cronista inglese, perché i vichinghi lo facevano troppo spesso?', 'Si lavavano e si pettinavano|Cantavano|Ballavano|Mangiavano verdura', 'Giovanni di Wallingford brontolava che facevano il bagno ogni sabato per fare colpo sulle donne inglesi.'],
    ['Il soldato giapponese Hiroo Onoda continuò a combattere la Seconda guerra mondiale nella giungla filippina fino a che anno?', '1974|1946|1950|1960', 'Si arrese solo quando il suo ex comandante arrivò di persona a ordinarglielo.'],
    ['Quale sovrano europeo ha regnato più a lungo?', 'Luigi XIV di Francia|La regina Vittoria|Elisabetta II|Francesco Giuseppe', 'Settantadue anni, a partire dall’età di quattro. Elisabetta II è seconda, con settanta.'],
    ['Nel 1978, che cosa successe alla bara di Charlie Chaplin?', 'Fu rubata per chiedere un riscatto|Fu spostata a Hollywood|Fu aperta per un film|Fu venduta all’asta', 'Due uomini la dissotterrarono in Svizzera e chiesero soldi. Ricomparve 11 settimane dopo, sepolta in un campo lì vicino.'],
    ['Mesi prima che John Wilkes Booth sparasse ad Abraham Lincoln, il fratello di Booth salvò la vita a chi?', 'Al figlio di Lincoln|A Lincoln in persona|Al generale Grant|A Booth stesso', 'L’attore Edwin Booth tirò via Robert Lincoln dai binari di un treno, nel New Jersey.'],
    ['Che cosa, si racconta, fu portato via dal funerale del presidente Andrew Jackson nel 1845?', 'Il suo pappagallo, perché diceva parolacce|Il suo cane, perché ululava|Un generale ubriaco|Una banda di ottoni', 'Un pastore presente scrisse che l’uccello bestemmiava così tanto che bisognò portarlo fuori.'],
    ['Dopo una battaglia nel 1325, i soldati di Modena portarono a casa da Bologna quale trofeo?', 'Un secchio di legno|Le ossa di un santo|La campana di una chiesa|Una forma di formaggio', 'La «secchia rapita», che ispirò il poema di Alessandro Tassoni. Una copia è ancora appesa nella Ghirlandina, il campanile del duomo di Modena.'],
  ],
  animals: [
    ['Come si chiama in inglese un branco di zebre?', 'Dazzle («abbaglio»)|Stripe («striscia»)|Barcode («codice a barre»)|Parade («sfilata»)', 'Le strisce forse confondono anche le mosche che pungono, che fanno fatica a posarsi.'],
    ['Come si chiama in inglese un gruppo di meduse?', 'Smack («schiaffo»)|Wobble («tremolio»)|Sting («puntura»)|Jelly («gelatina»)', 'Si può dire anche «bloom» o «swarm», ma «smack» è il più bello.'],
    ['Come si chiama in inglese un gruppo di istrici?', 'Prickle («aculeo»)|Needle («ago»)|Spine («spina»)|Pincushion («puntaspilli»)', 'E i piccoli di istrice in inglese si chiamano «porcupettes».'],
    ['Come si chiama in inglese un gruppo di furetti?', 'Business («affari»)|Mischief («birichinata»)|Gang («banda»)|Tunnel («galleria»)', 'I furetti furono addomesticati più di 2.000 anni fa per cacciare i conigli.'],
    ['Come si chiama in inglese il piccolo dell’echidna?', 'Puggle|Pupkin|Spiklet|Joey', 'Echidne e ornitorinchi sono gli unici mammiferi che depongono le uova.'],
    ['Quale uccello riesce a dormire mentre vola?', 'La fregata|Il pinguino|La gallina|Lo struzzo', 'Fa sonnellini di pochi secondi, spesso con mezzo cervello, durante voli che durano settimane.'],
    ['I rondoni possono restare in volo senza mai posarsi per quanto tempo?', 'Fino a 10 mesi|Circa 10 ore|Circa 10 giorni|Circa 2 anni', 'Mangiano, bevono e perfino dormono in volo.'],
    ['Quale animale ha il morso più potente mai misurato?', 'Il coccodrillo marino|Lo squalo bianco|Il leone|La iena', 'Oltre 16.000 newton, eppure i muscoli che aprono le fauci sono così deboli che si possono tenere chiuse a mano.'],
    ['Che cosa non può fare un coccodrillo?', 'Tirare fuori la lingua|Nuotare|Arrampicarsi|Correre', 'La lingua è tenuta giù da una membrana lungo il fondo della bocca.'],
    ['Quale animale ha la pelliccia più folta?', 'La lontra marina|L’orso polare|La volpe artica|Il bue muschiato', 'Circa 150.000 peli per centimetro quadrato, così la pelle non si bagna mai.'],
    ['Quale di questi animali vede la luce ultravioletta?', 'La renna|Il cavallo|La mucca|Il maiale', 'Le serve per individuare licheni e lupi contro la neve, che riflette gli UV.'],
    ['Quale animale produce il latte più grasso?', 'La cistofora|La mucca|La capra|Il cammello', 'Circa il 60% di grasso. I cuccioli allattano solo per circa quattro giorni e raddoppiano il loro peso.'],
    ['Più o meno quanto dormono ogni giorno le giraffe in natura?', 'Meno di 2 ore|Circa 8 ore|Circa 12 ore|Circa 18 ore', 'Spesso a sonnellini di pochi minuti, a volte in piedi.'],
    ['Di notte, le giraffe degli zoo sono state registrate mentre facevano che cosa?', 'Canticchiavano a bocca chiusa|Cantavano in armonia|Abbaiavano|Facevano le fusa', 'Uno studio del 2015 ha trovato un ronzio basso notturno. Nessuno sa ancora che cosa significhi.'],
    ['Di chi è il sangue blu usato per controllare che le medicine siano libere da germi?', 'Del limulo|Del polpo|Dell’aragosta|Del calamaro', 'Si coagula attorno alle tossine batteriche, quindi i laboratori lo usano per verificare che vaccini e iniezioni siano puliti.'],
    ['I limuli, i «granchi a ferro di cavallo», sono più strettamente imparentati con quale di questi?', 'I ragni|I granchi|Le aragoste|I gamberi', 'Nonostante il nome, sono parenti degli aracnidi, ed esistono da prima dei dinosauri.'],
    ['Quale animale ha una lingua che può essere più lunga del suo corpo?', 'Il camaleonte|La rana|Il formichiere|La giraffa', 'Scatta fuori e torna dentro in una frazione di secondo, con una punta appiccicosa a ventosa.'],
    ['Quanti occhi può avere una capasanta?', 'Fino a 200|2|8|Nessuno', 'File di minuscoli occhi blu corrono lungo la conchiglia, ognuno con un piccolo specchio dentro.'],
    ['La lingua di un picchio è così lunga che si avvolge intorno a che cosa?', 'Al cranio|Al collo|Al becco|All’ala', 'Le ossa della lingua girano intorno alla nuca, e forse aiutano ad attutire tutte quelle beccate.'],
    ['Quale lucertola riesce a correre sull’acqua?', 'Il basilisco|L’iguana|Il geco|Il drago di Komodo', 'Sbatte i piedi così in fretta che delle sacche d’aria lo tengono a galla per qualche metro.'],
    ['Quale animale ha gli occhi più grandi in proporzione al corpo?', 'Il tarsio|Il gufo|Il lemure|Il galagone', 'Ogni occhio è grande più o meno come il suo cervello. Non riesce a muoverli, quindi gira la testa.'],
    ['Quale grande felino non sa ruggire?', 'Il ghepardo|Il leone|La tigre|Il giaguaro', 'I ghepardi cinguettano, fanno le fusa e perfino miagolano.'],
    ['Sotto la pelliccia, anche la pelle della tigre è a strisce. Vero o falso?', 'Vero|Falso', 'Se rasassi una tigre, le strisce resterebbero lì, sulla pelle.'],
    ['Quante volte al giorno una mamma coniglio di solito allatta i piccoli?', 'Una volta al giorno, per pochi minuti|Ogni ora|Dieci volte al giorno|Una volta alla settimana', 'Per il resto del tempo sta lontana, così i predatori non trovano la tana.'],
    ['Con il fresco, quanto tempo può resistere un cammello senza bere?', 'Diverse settimane|Un giorno|Tre giorni|Un anno intero', 'Quando beve, riesce a mandar giù circa 100 litri in dieci minuti.'],
    ['Quante zampe può avere un millepiedi?', 'Più di 1.300|Esattamente 1.000|Meno di 100|Circa 10', 'Nessuno con 1.000 zampe era mai stato trovato fino al 2021, quando in Australia è spuntata una specie che ne ha fino a 1.306.'],
    ['Quale insetto fa il rumore più forte?', 'La cicala|Il grillo|L’ape|La zanzara', 'Alcune cicale superano i 100 decibel, rumorose come una motosega.'],
    ['Quale mammifero ha il record dell’immersione più lunga?', 'Lo zifio|Il capodoglio|L’elefante marino|Il tursiope', 'Uno è stato registrato sott’acqua per 3 ore e 42 minuti.'],
    ['Per quanto tempo i papà pinguino imperatore tengono al caldo l’uovo senza mangiare?', 'Circa due mesi|Circa due giorni|Circa una settimana|Circa un anno', 'Lo tengono in equilibrio sulle zampe per tutto l’inverno antartico e perdono fino al 45% del peso.'],
    ['Se un pulcino di pinguino imperatore nasce prima che torni la madre, con che cosa lo nutre il padre?', 'Con un liquido lattiginoso dalla gola|Con pesce messo da parte|Con la neve|Con niente', 'È una secrezione ricca di proteine che può far andare avanti il pulcino per qualche giorno.'],
    ['Quale animale può avere la pelliccia verde, perché ci crescono le alghe?', 'Il bradipo|L’orso polare|Il koala|L’orango', 'Le alghe lo aiutano a mimetizzarsi tra gli alberi, e alcune falene vivono solo nel pelo dei bradipi.'],
    ['Ogni quanto scendono dall’albero i bradipi?', 'Circa una volta alla settimana, per fare la cacca|Ogni ora|Una volta all’anno|Mai', 'Scendono nel loro posto preferito, scavano una buca e la fanno. Nessuno sa bene perché corrano questo rischio.'],
    ['Quale animale può cambiare sia il colore sia la consistenza della pelle?', 'Il polpo|Il camaleonte|La rana|Il serpente', 'I polpi fanno spuntare bozzi e punte per sembrare rocce e alghe.'],
    ['Quale pesce esce dall’acqua e si arrampica sulle radici delle mangrovie?', 'Il perioftalmo|Il pesce rosso|Il salmone|Il pesce pagliaccio', 'Cammina sulle pinne e, fuori dall’acqua, respira attraverso la pelle.'],
    ['L’anguilla elettrica in realtà non è un’anguilla. Che cos’è?', 'Un pesce coltello|Uno squalo|Un pesce gatto|Un serpente', 'La sua scossa può arrivare a circa 860 volt, la più forte di tutto il regno animale.'],
    ['Quale uccello sa imitare il rumore delle motoseghe e degli scatti delle macchine fotografiche?', 'L’uccello lira|Il pappagallo|Il mimo|Il corvo imperiale', 'Gli uccelli lira australiani imitano altri uccelli e i rumori umani che sentono vicino a casa.'],
    ['Il cuore di quale animale può battere più di 1.200 volte al minuto?', 'Il colibrì|Il topo|Il coniglio|Il passero', 'Il cuore del colibrì corre in volo, poi rallenta tantissimo quando di notte riposa.'],
    ['Più o meno quante formiche ci sono sulla Terra, secondo una stima del 2022?', '20 milioni di miliardi|20 milioni|20 miliardi|20.000', 'Sono circa 2,5 milioni di formiche per ogni persona.'],
    ['Che cosa fanno le formiche tagliafoglie con le foglie che trasportano?', 'Ci coltivano sopra un fungo da mangiare|Ci costruiscono le pareti del nido|Le mangiano|Le usano come ombrelli', 'Sono agricoltori: le foglie nutrono un orto di funghi, e il fungo nutre la colonia.'],
    ['Perché i denti dei castori sono arancioni?', 'Contengono ferro|Bevono acqua fangosa|Mangiano carote|Sono arrugginiti', 'Il ferro nello smalto li rende più resistenti per rosicchiare il legno.'],
    ['Quale insetto può vivere per decenni?', 'La regina delle termiti|La mosca|La farfalla|La zanzara', 'Alcune regine delle termiti vivono 25 anni o più, deponendo migliaia di uova al giorno.'],
    ['Quanto vive un’effimera adulta?', 'Da qualche minuto a un giorno o due|Circa un mese|Circa un anno|Circa una settimana', 'Molte non hanno nemmeno una bocca funzionante. Le larve, però, vivono sott’acqua fino a due anni.'],
    ['Quale uccello ha circa 25.000 piume, uno dei numeri più alti conosciuti?', 'Il cigno minore|Il colibrì|Il pinguino|La gallina', 'Un colibrì golarubino ne ha meno di 1.000.'],
    ['Quale paese non ha serpenti autoctoni?', 'L’Irlanda|L’Inghilterra|La Francia|L’Italia', 'La leggenda ne dà il merito a san Patrizio. In realtà i serpenti non ci arrivarono prima che il mare, salendo, isolasse l’Irlanda.'],
    ['Un panda gigante appena nato è grande più o meno come che cosa?', 'Un panetto di burro|Un cagnolino|Un gatto|Un orsacchiotto', 'È rosa, quasi senza pelo, e pesa circa 1/900 della madre.'],
    ['Gli squali esistono da più tempo degli alberi. Vero o falso?', 'Vero|Falso', 'Gli squali risalgono a circa 450 milioni di anni fa. I primi alberi comparvero intorno a 385 milioni di anni fa.'],
    ['Quanti denti può consumare uno squalo nella sua vita?', 'Decine di migliaia|Circa 30|Circa 100|Un solo set', 'I denti stanno in file, come su un nastro trasportatore. Uno perso viene sostituito in pochi giorni.'],
    ['Come si chiama in inglese un gruppo di rinoceronti?', 'Crash («schianto»)|Thunder («tuono»)|Bump («botta»)|Stampede («fuggi fuggi»)', 'I rinoceronti possono correre a circa 50 km/h, anche se pesano più di due tonnellate.'],
    ['Il corno di quale animale è fatto della stessa sostanza delle tue unghie?', 'Del rinoceronte|Del cervo|Dell’alce|Del wapiti', 'È cheratina compatta, senza osso dentro: ecco perché non ha nessun valore medicinale.'],
    ['I palchi dei cervi cadono e ricrescono ogni anno. Quanto in fretta possono crescere?', 'Più di 2 cm al giorno|1 mm alla settimana|1 cm al mese|Crescono solo di notte', 'I palchi sono tra i tessuti a crescita più rapida che si conoscano.'],
    ['In quale tipo di cervide anche le femmine hanno i palchi?', 'La renna|Il cervo nobile|L’alce|Il cervo dalla coda bianca', 'Le femmine li tengono tutto l’inverno, quando i maschi li hanno già persi: quindi le renne della slitta di Natale potrebbero essere tutte femmine.'],
    ['Nel 2022 una pittima minore volò senza sosta dall’Alaska alla Tasmania. Quanto ci mise?', 'Circa 11 giorni|Circa 11 ore|Circa un mese|Circa 3 giorni', 'Circa 13.500 km senza posarsi, mangiare né bere.'],
    ['Quali scimmie antropomorfe si costruiscono ogni notte un letto nuovo di foglie?', 'Gli scimpanzé|I gibboni|I babbuini|I lemuri', 'Intrecciano i rami a formare un materasso in cima agli alberi, spesso in meno di cinque minuti.'],
    ['Da quanto lontano si sente un gorilla che si batte il petto?', 'Da circa 1 km|Da circa 10 m|Da circa 100 m|Da circa 10 km', 'I maschi più grossi fanno un tamburellare più profondo, ha scoperto uno studio del 2021.'],
    ['Che cosa significa «orangutan» in malese?', 'Uomo della foresta|Scimmia rossa|Braccia lunghe|Arrampicatore', 'Passano quasi tutta la vita sugli alberi e si costruiscono nidi per dormire.'],
    ['Perché il naso dei cani di solito è bagnato?', 'L’umidità aiuta a catturare gli odori|Starnutiscono spesso|Lo intingono nella ciotola|Gli raffredda il cervello', 'Il muco intrappola le particelle d’odore, e leccandosi il naso le portano a un organo dell’olfatto nella bocca.'],
    ['Per cacciare quale animale furono selezionati i bassotti?', 'Il tasso|Il ratto|Lo scoiattolo|L’anatra', 'In tedesco «Dachs» vuol dire tasso. Il corpo lungo entrava nelle tane.'],
    ['Per che cosa furono selezionati all’inizio i barboncini?', 'Per riportare le anatre dall’acqua|Per radunare le pecore|Per fare la guardia ai palazzi|Per correre', '«Pudel» viene dal tedesco per «sguazzare». La toelettatura buffa teneva calde le articolazioni.'],
    ['Come fa un gatto che cade ad atterrare sulle zampe?', 'Si torce a mezz’aria|La coda fa da timone|Si allarga come un paracadute|Pura fortuna', 'Una colonna vertebrale molto flessibile gli permette di girare prima la parte davanti, poi quella dietro, anche in una caduta breve.'],
    ['Perché la lingua del gatto è ruvida?', 'È coperta di minuscoli uncini rivolti all’indietro|È secca|Ha dei denti|È piena di sabbia', 'Gli uncini pettinano il pelo e raschiano la carne dalle ossa.'],
    ['Quanto è grande l’uovo del kiwi, rispetto alla madre?', 'Circa il 20% del suo peso|L’1%|Il 5%|Il 50%', 'Per una donna sarebbe come partorire un bambino di quattro anni.'],
    ['Quale creatura può farsi ricrescere una testa nuova, cervello compreso?', 'Una planaria|Un lombrico|Una lumaca|Una rana', 'Taglia una planaria a pezzi, e ogni pezzo può diventare un verme completo.'],
    ['Come si difendono alcune oloturie, i cetrioli di mare?', 'Sparando fuori le budella|Mordendo|Girando su se stesse|Brillando', 'Poi gli organi persi ricrescono.'],
    ['Da quale parte respirano le oloturie?', 'Dal sedere|Dalla bocca|Dalle branchie sulla testa|Da nessuna delle due', 'L’acqua viene pompata dentro e fuori dalla parte posteriore. Alcuni pesciolini ci vivono perfino dentro.'],
    ['Di che colore brilla un ornitorinco alla luce UV?', 'Blu-verde|Rosso|Giallo|Viola', 'Gli scienziati se ne accorsero nel 2020 su esemplari da museo. Nessuno sa ancora perché.'],
    ['Quale animale ha il cervello più grande?', 'Il capodoglio|L’elefante|La balenottera azzurra|L’uomo', 'Pesa circa 8 kg, più o meno sei volte il nostro.'],
    ['La lingua di una balenottera azzurra può pesare più o meno quanto che cosa?', 'Un elefante|Un gatto|Una gomma d’auto|Un divano', 'Circa 2,7 tonnellate.'],
    ['Come catturano i pesci le megattere?', 'Soffiano reti di bolle|Li schiaffeggiano con le pinne|Li fanno addormentare cantando|Si nascondono tra le alghe', 'Nuotano a spirale soffiando bolle che intrappolano i pesci, poi risalgono a bocca aperta nel mezzo.'],
    ['Che cosa hanno di strano i canti delle megattere?', 'Tutti i maschi di una zona cantano la stessa canzone|Cantano solo le femmine|Cantano una sola volta nella vita|Cantano in codice Morse', 'La canzone comune cambia lentamente, e le canzoni nuove possono passare da un oceano all’altro.'],
    ['Che cosa fanno i pipistrelli vampiro per un amico affamato?', 'Gli rigurgitano un po’ di sangue|Niente|Cacciano per lui|Dividono gli insetti', 'I pipistrelli che erano stati nutriti condividevano di più con quelli che li avevano aiutati prima.'],
    ['Quanti tipi di recettori del colore ha una canocchia pavone, rispetto ai nostri tre?', 'Da 12 a 16|3|5|100', 'Stranamente, i test fanno pensare che non sia più brava di noi a distinguere colori simili.'],
    ['Il nido di quale uccello si cucina in una famosa zuppa?', 'La salangana|Il passero|La rondine|Il piccione', 'I nidi sono fatti di saliva indurita e possono costare migliaia di dollari al chilo.'],
    ['A che velocità può correre un ippopotamo sulla terraferma?', 'Circa 30 km/h|Circa 5 km/h|Circa 70 km/h|Non sa correre', 'In compenso, gli ippopotami nuotano male: camminano o saltellano sul fondo.'],
    ['Come fa una volpe a catturare i topi sotto la neve?', 'Salta in alto e si tuffa di testa|Scava un lungo tunnel|Aspetta vicino alle tane|Li fiuta solo dall’alto', 'Li ascolta sotto la neve. Secondo uno studio, i salti riuscivano meglio rivolti più o meno a nord-est.'],
    ['Una falena può ricordare qualcosa che ha imparato da bruco?', 'Sì|No', 'In uno studio del 2008, i bruchi addestrati a evitare un odore lo evitavano ancora da falene, anche se nel bozzolo il loro corpo era diventato una specie di brodo.'],
    ['Quale animale ha due rotule per ogni ginocchio?', 'Lo struzzo|Il cavallo|Il canguro|Il cammello', 'Nessuno sa bene perché. Quasi tutti gli uccelli ne hanno una o nessuna.'],
    ['Che cosa tengono le lontre marine in una tasca di pelle sotto le zampe anteriori?', 'Un sasso preferito per rompere i gusci|I cuccioli|Pelo di scorta|Uova di pesce', 'Alcune si portano dietro lo stesso sasso per anni.'],
    ['Quale di queste cose non sa fare un elefante adulto?', 'Saltare|Nuotare|Correre|Sdraiarsi', 'Tiene sempre almeno una zampa a terra, anche quando va di fretta.'],
    ['In Amazzonia, alcune farfalle bevono che cosa?', 'Le lacrime delle tartarughe|Solo acqua piovana|Sangue di scimmia|Veleno di serpente', 'Le lacrime sono salate, e nella foresta pluviale il sale è raro.'],
    ['Che cosa manca a un ornitorinco?', 'Lo stomaco|Il cuore|La coda|Gli occhi', 'L’esofago si collega direttamente all’intestino. Anche le echidne non hanno lo stomaco.'],
    ['Qual è il pappagallo più pesante del mondo, che non sa volare?', 'Il kakapo|L’ara|Il cacatua|Il kea', 'Vive decenni, ha un odore dolce e di muffa, e ne restano solo un paio di centinaia.'],
    ['In Giappone, quali animali selvatici d’inverno fanno il bagno nelle sorgenti termali?', 'I macachi delle nevi|Gli orsi|I cervi|Le volpi', 'Uno studio del 2018 ha scoperto che il bagno abbassava i loro ormoni dello stress.'],
    ['Che cosa, in un cane, è unico come le tue impronte digitali?', 'L’impronta del naso|I cuscinetti delle zampe|L’abbaio|La coda', 'Alcune app e alcuni club cinofili hanno usato le impronte del naso per identificare i cani.'],
    ['Che cosa non sanno fare i ratti?', 'Vomitare|Nuotare|Arrampicarsi|Saltare', 'È anche per questo che il veleno per topi funziona così bene. Nemmeno i cavalli possono vomitare.'],
    ['Che cosa riescono a percepire i bombi intorno ai fiori?', 'Il loro campo elettrico|Solo la temperatura|La loro età|Niente', 'Uno studio del 2013 ha scoperto che i bombi capiscono quali fiori sono appena stati visitati dalla minuscola carica lasciata dagli altri.'],
    ['Come rompono le noci alcuni corvi di città in Giappone?', 'Le lasciano sulle strisce perché le schiaccino le auto|Usano dei martelli|Le lanciano contro le finestre|Le danno alle persone', 'Alcuni sembrano perfino aspettare che il semaforo cambi prima di andare a raccogliere i pezzi.'],
    ['Che cosa riescono a fare a malapena i colibrì?', 'Camminare|Volare all’indietro|Vedere il rosso|Restare sospesi in volo', 'Le loro zampette servono per appollaiarsi. Per spostarsi lungo un ramo, volano.'],
    ['Come mangia un fenicottero?', 'A testa in giù|Solo stando su una zampa|Tuffandosi sott’acqua|Prendendo i pesci al volo', 'Il becco ricurvo funziona capovolto e filtra dall’acqua il cibo minuscolo.'],
    ['Gli elefanti captano i brontolii lontani degli altri elefanti attraverso che cosa?', 'Le zampe|Le zanne|La coda|Le ciglia', 'I brontolii bassi viaggiano nel terreno per chilometri, e dei punti sensibili nelle zampe e nella proboscide li sentono.'],
    ['Gli scienziati hanno filmato dei polpi mentre facevano che cosa ai pesci con cui cacciano insieme?', 'Prenderli a pugni|Abbracciarli|Dargli da mangiare|Cantargli qualcosa', 'Pesci e polpi fanno squadra per cacciare. I pugni sembrano servire a tenere in riga i compagni pigri o ingordi.'],
  ],
  science: [
    ['Quanto ci mette il sangue a fare un giro completo del corpo?', 'Circa un minuto|Circa un’ora|Circa un giorno|Circa un secondo', 'A riposo il cuore pompa circa 5 litri al minuto.'],
    ['Messi in fila, quanto sarebbero lunghi tutti i vasi sanguigni di un adulto?', 'Circa 100.000 km|Circa 1 km|Circa 100 km|Circa 10 milioni di km', 'Abbastanza da fare il giro della Terra più di due volte.'],
    ['Qual è il muscolo più forte del corpo, in proporzione alla sua grandezza?', 'Il muscolo della mascella|La lingua|Il cuore|La coscia', 'Il massetere può stringere i denti posteriori con una forza fino a circa 900 newton.'],
    ['Quale parte del corpo non riceve nemmeno una goccia di sangue?', 'Lo smalto dei denti|L’orecchio|Il naso|Le labbra', 'Lo smalto non è un tessuto vivo, quindi non può ripararsi da solo.'],
    ['Perché nella vasca da bagno le dita si raggrinziscono?', 'I nervi restringono i vasi sanguigni per migliorare la presa|Assorbono acqua come una spugna|La pelle si scioglie|È colpa del sapone', 'Chi ha i nervi delle dita danneggiati non si raggrinzisce: segno che è una reazione attiva.'],
    ['Il naso riesce a distinguere più o meno quanti odori?', 'Forse più di mille miliardi|Circa 100|Circa 10.000|Circa 10', 'Uno studio del 2014 è arrivato a questa stima mescolando odori. Altri scienziati pensano che siano meno, ma comunque tantissimi.'],
    ['Quando arrossisci, che cos’altro diventa rosso?', 'La parete dello stomaco|Le unghie dei piedi|I capelli|Niente', 'Si dilatano anche i vasi sanguigni della parete dello stomaco.'],
    ['Si può starnutire a occhi aperti?', 'Sì, ma è difficilissimo|No, mai|Solo il lunedì|Solo tappandosi il naso', 'Chiudere gli occhi è un riflesso, non una protezione per non farli schizzare fuori.'],
    ['Come vedono il mondo gli occhi prima che il cervello lo sistemi?', 'Capovolto|In bianco e nero|Di lato|Al contrario, da destra a sinistra', 'Il cristallino ribalta l’immagine sulla retina, e il cervello la rimette dritta.'],
    ['A che cosa sembra servire l’appendice?', 'A custodire batteri intestinali utili|A niente di niente|A digerire l’erba|A produrre sangue', 'Potrebbe fare da rifugio per i batteri buoni dopo una malattia che ha svuotato l’intestino.'],
    ['Su quale mano, di solito, le unghie crescono più in fretta?', 'Su quella con cui scrivi|Sull’altra|Su tutte e due allo stesso modo|Dipende dal tempo', 'Alcuni studi collegano una crescita più veloce a un uso maggiore e a più afflusso di sangue.'],
    ['Quale elemento prende il nome dal Sole?', 'L’elio|Il solio|L’idrogeno|Il sodio', 'Dal greco hélios: fu individuato nella luce del Sole nel 1868, prima di essere trovato sulla Terra.'],
    ['Un fulmine può fondere la sabbia trasformandola in che cosa?', 'Tubi di vetro|Oro|Diamanti|Sale', 'Si chiamano folgoriti, o fulmini pietrificati.'],
    ['Di che colore è davvero il Sole?', 'Bianco|Giallo|Arancione|Rosso', 'Sembra giallo attraverso la nostra atmosfera, che disperde la luce blu. Dallo spazio appare bianco.'],
    ['Pesa di più l’acqua calda o quella fredda?', 'Quella fredda, a parità di volume|Quella calda|Pesano uguale|Dipende dalla tazza', 'L’acqua è più densa intorno ai 4 °C: ecco perché sul fondo di un lago ghiacciato l’acqua resta liquida.'],
    ['Nel vuoto, che cosa cade più in fretta: un martello o una piuma?', 'Nessuno dei due: arrivano insieme|Il martello|La piuma|Galleggiano', 'L’astronauta dell’Apollo 15 David Scott lo dimostrò sulla Luna nel 1971.'],
    ['Secondo Isaac Newton, quanti colori ha l’arcobaleno, e perché?', 'Sette, come le note musicali|Cinque, come le dita|Tre, come i colori primari|Dodici, come i mesi', 'Aggiunse l’arancione e l’indaco anche perché i colori corrispondessero alle sette note della scala musicale.'],
    ['Perché una conchiglia sembra contenere il rumore del mare?', 'Amplifica i rumori intorno a te|Ha registrato le onde|Ne esce dell’aria|Il tuo sangue fa così tanto rumore', 'Qualsiasi tazza o mano sull’orecchio fa lo stesso.'],
    ['Che cosa produce lo schiocco di una frusta?', 'La punta che supera la barriera del suono|Il manico che si spezza|L’aria che esce dal cuoio|Un’eco', 'La frusta è stato il primo oggetto costruito dall’uomo a superare la velocità del suono.'],
    ['I poli magnetici della Terra ogni tanto fanno che cosa?', 'Si scambiano di posto|Spariscono per sempre|Fermano la rotazione del pianeta|Diventano ghiaccio', 'È successo centinaia di volte. L’ultima inversione completa è stata circa 780.000 anni fa.'],
    ['Qual è il parente vivente più stretto dell’ippopotamo?', 'Le balene|I maiali|I cavalli|I rinoceronti', 'Ippopotami e balene hanno un antenato comune vissuto circa 55 milioni di anni fa.'],
    ['Se si sciogliesse tutto il ghiaccio della Terra, di quanto si alzerebbe il mare?', 'Circa 70 m|Circa 1 m|Circa 10 m|Circa 700 m', 'L’Antartide contiene circa il 90% di tutto il ghiaccio.'],
    ['Il Tyrannosaurus rex è vissuto più vicino nel tempo a noi che a quale dinosauro?', 'Lo stegosauro|Il triceratopo|Il velociraptor|Lo spinosauro', 'Lo stegosauro si estinse circa 80 milioni di anni prima che comparisse il T. rex.'],
    ['Quanti cuori hanno i lombrichi, per così dire?', 'Cinque paia|Uno|Nessuno|Due', 'Sono vasi sanguigni che pompano, chiamati archi aortici.'],
    ['Da dove viene la maggior parte dell’ossigeno che respiriamo?', 'Dal minuscolo plancton degli oceani|Dalle foreste pluviali|Dall’erba|Dai vulcani', 'Il fitoplancton produce circa metà dell’ossigeno della Terra.'],
    ['Quanti anni ha l’albero vivente più vecchio che si conosca?', 'Più di 4.800|Circa 500|Circa 1.000|Circa 50.000', 'È un pino dai coni setolosi della California chiamato Matusalemme. La sua posizione è tenuta segreta.'],
    ['Secondo la propaganda britannica di guerra, che cosa davano le carote ai piloti?', 'La vista al buio|Una forza sovrumana|Il coraggio|Riflessi più pronti', 'Serviva a coprire il vero segreto: il radar.'],
    ['Perché il gelato fa venire il «mal di testa da freddo»?', 'I vasi sanguigni della testa reagiscono al freddo|Il cervello gela un po’|I denti vanno nel panico|Troppo zucchero', 'Premere la lingua contro il palato lo scalda e aiuta.'],
    ['Che cosa causa il singhiozzo?', 'Il diaframma che si contrae all’improvviso|Aria ingoiata nei polmoni|Il cuore che salta un battito|Il ridere troppo', 'L’«hic» sono le corde vocali che si chiudono di scatto.'],
    ['Perché sbadigli quando vedi qualcun altro sbadigliare?', 'Nessuno lo sa con certezza|Per avere più ossigeno|Il cervello copia tutto|Per rinfrescare i denti', 'Perfino i cani possono «prendere» uno sbadiglio dai padroni.'],
    ['Che cosa fa fare le fusa a un gatto?', 'I muscoli della laringe che vibrano|Un osso speciale della gola|L’aria nella pancia|Il battito del cuore', 'I muscoli vibrano da 25 a 150 volte al secondo mentre il gatto inspira ed espira.'],
    ['Quale senso si sviluppa per primo in un bambino prima della nascita?', 'Il tatto|La vista|L’udito|L’olfatto', 'Intorno alla 25ª settimana i bambini sentono anche i suoni che arrivano da fuori della pancia.'],
    ['Esistono davvero persone «da emisfero sinistro» e «da emisfero destro»?', 'No, usiamo tutti e due|Sì, ognuno è o l’uno o l’altro|Solo gli artisti|Solo i gemelli', 'Le scansioni cerebrali di più di 1.000 persone non hanno trovato traccia di un lato dominante.'],
    ['In un essere umano, è più lunga l’apertura delle braccia o l’altezza?', 'Più o meno uguali|L’apertura è il doppio|L’altezza è il doppio|L’apertura è sempre più corta', 'Leonardo da Vinci lo annotò nel disegno dell’Uomo vitruviano.'],
    ['Qual è l’elemento più comune nella crosta terrestre?', 'L’ossigeno|Il ferro|Il silicio|L’alluminio', 'L’ossigeno è quasi metà della crosta, per lo più chiuso nelle rocce.'],
    ['Qual è il metallo più comune nella crosta terrestre?', 'L’alluminio|Il ferro|Il rame|L’oro', 'Un tempo era così difficile da estrarre da costare più dell’oro, e Napoleone III offriva ai suoi ospiti migliori posate di alluminio.'],
    ['Se togliessi tutto lo spazio vuoto dai loro atomi, l’intera umanità starebbe in che cosa?', 'In una zolletta di zucchero|In uno stadio|In una piscina|In una piccola città', 'Gli atomi sono quasi interamente vuoti. Compressi come una stella di neutroni, peseremmo lo stesso ma staremmo in circa 1 cm³.'],
    ['Nel suo «punto triplo», l’acqua può fare che cosa?', 'Bollire e gelare nello stesso momento|Brillare|Galleggiare su se stessa|Diventare metallo', 'A 0,01 °C e a una pressione bassissima, ghiaccio, acqua liquida e vapore esistono tutti insieme.'],
    ['In quale posto inaspettato sono stati trovati recettori del gusto amaro?', 'Nei polmoni|Nelle unghie|Nei capelli|Nelle ossa', 'Nelle vie respiratorie sembrano aiutare a combattere i germi. Altri si trovano nell’intestino.'],
    ['Perché non riesci a farti il solletico da solo?', 'Il cervello prevede il tocco e lo attenua|La pelle è abituata a te|I nervi si spengono|Ridi troppo presto', 'Il cervelletto prevede che effetto faranno i tuoi stessi movimenti.'],
    ['Perché la tua voce registrata suona così strana?', 'Di solito la senti anche attraverso le ossa del cranio|I microfoni la distorcono|Hai le orecchie tappate|Gli altoparlanti aggiungono un’eco', 'La conduzione ossea aggiunge toni bassi, quindi la registrazione suona più acuta e sottile. Ed è così che ti sentono tutti gli altri.'],
    ['Taglia un acino d’uva quasi a metà e mettilo nel microonde. Che cosa succede?', 'Forma una palla di plasma luminoso|Esplode in succo|Niente|Diventa uvetta', 'Le due metà concentrano le microonde come un’antenna. Non provarci: puoi rovinare il forno.'],
    ['Quanta parte dell’universo è fatta di materia ordinaria, quella di stelle, pianeti e persone?', 'Circa il 5%|Circa il 50%|Circa il 95%|Tutto', 'Il resto è materia oscura ed energia oscura, che nessuno ha mai rilevato direttamente.'],
    ['Contando un numero al secondo, senza mai fermarti, quanto ci metteresti ad arrivare a un miliardo?', 'Circa 32 anni|Circa 3 anni|Circa 320 anni|Circa una settimana', 'Un milione di secondi sono circa 11 giorni e mezzo. Un miliardo, circa 31,7 anni.'],
    ['Se srotolassi tutto il DNA del tuo corpo, più o meno fin dove arriverebbe?', 'Al Sole e ritorno decine di volte|Intorno a un campo da calcio|Da un capo all’altro di una città|Alla Luna', 'Il nucleo di ogni cellula contiene circa 2 m di DNA, e tu hai migliaia di miliardi di cellule.'],
    ['Che aspetto ha la fiamma di una candela in assenza di gravità?', 'Una palla blu e rotonda|Una normale fiamma a punta|Punta verso il basso|Si spegne subito', 'Senza aria calda che sale, la fiamma si allarga in modo uguale in tutte le direzioni.'],
    ['Perché gli uccelli sui fili dell’alta tensione non restano fulminati?', 'Toccano un solo filo, quindi in loro non passa corrente|Hanno le zampe di gomma|I fili sono isolati|Restano fulminati, ma non fa male', 'Se però toccano nello stesso momento un secondo filo o il palo, la corrente prende la scorciatoia.'],
    ['Se la storia della Terra fosse compressa in un solo giorno, quando comparirebbero gli esseri umani moderni?', 'Negli ultimi secondi prima di mezzanotte|A mezzogiorno|Alle 18|Nell’ultima ora', 'I dinosauri si sarebbero estinti appena 21 minuti circa prima di mezzanotte.'],
    ['Di che colore è l’ossigeno liquido?', 'Azzurro pallido|Trasparente|Verde|Argento', 'Ed è magnetico: resta attaccato tra i poli di una calamita potente.'],
    ['Che cosa produce lo schiocco quando ti scrocchi le dita?', 'Una bolla di gas che si forma nel liquido dell’articolazione|Le ossa che sfregano|Un tendine che scatta|La cartilagine che si rompe', 'Dei video di risonanza magnetica nel 2015 l’hanno ripreso mentre succedeva. Per questo bisogna aspettare circa 20 minuti per rifarlo.'],
    ['Il tuo naso è sempre nel tuo campo visivo. Perché non lo vedi?', 'Il cervello lo cancella|È troppo sfocato|Gli occhi non riescono a guardare lì|Lo elimini sbattendo le palpebre', 'Chiudi un occhio e guarda in basso: eccolo.'],
    ['A che velocità viaggiano i segnali nervosi più veloci del corpo?', 'Circa 430 km/h|Alla velocità della luce|Circa 4 km/h|Circa 43.000 km/h', 'I segnali del dolore sono molto più lenti: ecco perché un dito del piede sbattuto fa male un attimo dopo il colpo.'],
    ['Nel buio totale, qual è la quantità più piccola di luce che un occhio umano potrebbe percepire?', 'Un solo fotone|Circa un milione di fotoni|Solo la fiamma di una candela|Solo un fiammifero acceso', 'In uno studio del 2016, le persone se la cavavano un po’ meglio del caso nel notare fotoni singoli.'],
    ['Che cosa è spesso una delle cose più piene di germi in casa?', 'La spugna da cucina|L’asse del water|Il telecomando|Il campanello', 'Uno studio del 2017 ha trovato fino a 54 miliardi di batteri in un centimetro cubo di spugna usata.'],
    ['Che cosa inverte davvero uno specchio?', 'Davanti e dietro|Destra e sinistra|Alto e basso|Niente', 'Il tuo riflesso sembra scambiare le mani solo perché ti sta di fronte. Lo specchio inverte solo la profondità.'],
    ['Gli esseri umani hanno più o meno tanti follicoli piliferi quanti quale animale?', 'Uno scimpanzé|Un topo senza pelo|Un pesce rosso|Un serpente', 'Solo che quasi tutti i nostri peli sono molto più sottili e corti.'],
    ['Stesa in piano, la superficie interna dei tuoi polmoni coprirebbe più o meno che cosa?', 'Il pavimento di un piccolo appartamento|Un piatto|Un campo da calcio|Un francobollo', 'Circa 50–75 m², grazie a centinaia di milioni di minuscoli alveoli.'],
    ['Di che cosa sa il sudore fresco?', 'Di quasi niente|Di cipolla|Di aceto|Di sale', 'L’odore arriva dopo, quando i batteri sulla pelle lo decompongono.'],
    ['Quale sapore i neonati non riescono ancora a sentire?', 'Il salato|Il dolce|L’aspro|L’amaro', 'La capacità di sentire il salato sembra comparire verso i quattro mesi. La passione per il dolce c’è fin dalla nascita.'],
    ['La neve è fatta di ghiaccio trasparente. Perché sembra bianca?', 'Le facce dei cristalli diffondono tutti i colori|Contiene sale|L’aria la fa bianca|Riflette le nuvole', 'Un blocco spesso di puro ghiaccio di ghiacciaio può sembrare perfino blu.'],
  ],
  food: [
    ['Che cosa sono davvero i chicchi di caffè?', 'Semi di un frutto simile a una ciliegia|Legumi, come i piselli|Frutta secca|Radici', 'Ogni ciliegia di caffè di solito contiene due semi.'],
    ['Secondo la leggenda, chi scoprì il caffè?', 'Un pastore le cui capre diventavano vivacissime|Un monaco che si era addormentato|Un marinaio|Un fornaio', 'La storia di Kaldi, in Etiopia, è probabilmente inventata, ma il caffè viene davvero da lì.'],
    ['Che cosa sono davvero i chiodi di garofano?', 'Boccioli di fiore essiccati|Semi|Bacche|Radici', 'Vengono da un albero originario delle isole delle Spezie, in Indonesia.'],
    ['Il pepe nero, bianco e verde vengono dalla stessa pianta. Vero o falso?', 'Vero|Falso', 'Il verde è acerbo, il nero è acerbo ed essiccato, il bianco è il seme maturo senza la buccia.'],
    ['Da che tipo di pianta viene la vaniglia?', 'Da un’orchidea|Da un cespuglio di fagioli|Da una palma|Da un giglio', 'Fuori dal Messico i fiori si impollinano a mano: ecco perché la vaniglia costa così tanto.'],
    ['Perché dopo il peperoncino il latte rinfresca la bocca meglio dell’acqua?', 'Una proteina del latte cattura la sostanza che brucia|È più freddo|È più dolce|Ricopre i denti', 'La caseina si lega alla capsaicina e la porta via. L’acqua la sparge soltanto.'],
    ['Quale ortaggio fu coltivato sullo Space Shuttle nel 1995?', 'La patata|La lattuga|Il pomodoro|La carota', 'A bordo del Columbia crebbero minuscoli tuberi di patata.'],
    ['Più di un quarto delle nocciole del mondo finisce in che cosa?', 'Nella Nutella|Nelle tavolette di cioccolato|Nel gelato|Nelle mangiatoie per uccelli', 'La maggior parte delle nocciole si coltiva in Turchia.'],
    ['Gli scienziati hanno scoperto che i buchi dell’Emmental svizzero, per formarsi, hanno bisogno di che cosa?', 'Di minuscoli granelli di polvere di fieno|Di bolle d’aria delle mucche|Di buchi negli stampi|Di cristalli di sale', 'Il gas lo producono i batteri, ma le bolle nascono intorno ai granelli di fieno.'],
    ['Nel 2019, una coppia di che cosa fu venduta a un’asta in Giappone per circa 45.000 dollari?', 'Meloni Yubari King|Mele|Fragole|Uva', 'In Giappone i primi meloni della stagione sono un regalo di lusso.'],
    ['Come fanno i contadini giapponesi a coltivare angurie quadrate?', 'In scatole quadrate|Incrociandole|Schiacciandole dopo|Intagliandole', 'Sono soprattutto decorative e spesso vengono raccolte prima di essere mature.'],
    ['Quale frutto esiste in più di 7.500 varietà?', 'La mela|La banana|L’uva|Il mango', 'Assaggiandone una nuova ogni giorno ci vorrebbero più di 20 anni.'],
    ['La Cavendish è la varietà più diffusa al mondo di che cosa?', 'Di banana|Di mela|Di patata|Di caffè', 'Quasi tutte le banane dei negozi sono cloni, e questo le rende vulnerabili alle malattie.'],
    ['Che fine ha fatto la Gros Michel, la banana che tutti mangiavano prima degli anni Cinquanta?', 'Una malattia ha distrutto quasi tutte le piantagioni|È stata vietata|È diventata blu|È diventata troppo cara', 'Si dice che sapesse molto di più dell’aroma artificiale di banana.'],
    ['Il durian è vietato su molti treni del Sud-est asiatico per che cosa?', 'Per l’odore|Per le spine|Per le macchie del succo|Per il peso', 'I fan dicono che sa di crema pasticcera. I detrattori paragonano l’odore a cipolle marce.'],
    ['Il formaggio trovato insieme ad alcune mummie in Cina ha più o meno quanti anni?', 'Circa 3.600|Circa 600|Circa 36|Circa 36.000', 'Era un formaggio simile al kefir, spalmato sul collo e sul petto dei corpi.'],
    ['Quale paese beve più tè a persona?', 'La Turchia|Il Regno Unito|La Cina|L’India', 'Più di 3 kg a testa all’anno, servito in piccoli bicchieri a forma di tulipano.'],
    ['Il tè verde e il tè nero vengono dalla stessa pianta. Vero o falso?', 'Vero|Falso', 'La Camellia sinensis. Il tè nero viene semplicemente lasciato ossidare prima di essere essiccato.'],
    ['Dove furono inventate, per caso, le bustine di tè?', 'A New York|A Londra|A Delhi|A Pechino', 'Intorno al 1908 un commerciante mandava campioni in sacchetti di seta, e i clienti li immergevano interi.'],
    ['Il cappuccino prende il nome da che cosa?', 'Dal saio dei frati cappuccini|Da una città|Da una tazza|Da una mucca', 'Il colore ricordava i cappucci marroni dei frati cappuccini.'],
    ['Una bottiglia di champagne contiene più o meno quanta pressione, rispetto a una gomma d’auto?', 'Circa tre volte tanto|Più o meno uguale|La metà|Dieci volte tanto', 'Ecco perché un tappo può volare via a circa 40 km/h.'],
    ['Più o meno quante bollicine ci sono in un bicchiere di champagne?', 'Circa un milione|Circa 100|Circa 10.000|Circa un miliardo', 'Uno studio del 2014 ne ha stimato circa un milione in un flûte.'],
    ['Chi promosse il pad thai come piatto nazionale negli anni Trenta e Quaranta?', 'Il governo thailandese|Un cuoco famoso|Una catena di alberghi|Un programma tv', 'Doveva rafforzare l’orgoglio nazionale e far consumare meno riso durante le carestie.'],
    ['In Iran, come soprannominano i pistacchi, perché il guscio si apre?', 'Il seme che sorride|Il seme che ride|La perla verde|Il seme che canta', 'In Cina li chiamano il seme felice.'],
    ['A parità di peso, che cosa ha più potassio?', 'Un avocado|Una banana', 'Gli avocado ne hanno circa un terzo in più.'],
    ['Più o meno quanti semi ci sono sulla superficie di una fragola?', 'Circa 200|Circa 10|Circa 1.000|Circa 50', 'Ogni «seme» è in realtà un minuscolo frutto con un seme dentro.'],
    ['Come si raccolgono i mirtilli rossi americani?', 'Allagando le torbiere, così galleggiano|Scuotendo gli alberi|A mano, uno per uno|Con l’aspirapolvere', 'Le sacche d’aria all’interno li fanno risalire, e vengono raccolti dalla superficie dell’acqua.'],
    ['Perché in inglese il pompelmo si chiama «grapefruit», «frutto-uva»?', 'Cresce a grappoli, come l’uva|Sa d’uva|È stato incrociato con l’uva|Per un contadino di nome Grape', 'Nacque alle Barbados nel Settecento, da un incrocio tra pomelo e arancia.'],
    ['In inglese, che cosa è arrivato prima: «orange» il frutto o «orange» il colore?', 'Il frutto|Il colore', 'Prima che arrivasse il frutto, chi parlava inglese chiamava quel colore «giallo-rosso». Anche il nostro arancione viene dall’arancia.'],
    ['Che cosa significa Theobroma, il nome latino della pianta del cacao?', 'Cibo degli dei|Fagiolo amaro|Gioia scura|Oro bruno', 'Glielo diede Linneo nel 1753.'],
    ['In quale paese è stato inventato il cioccolato al latte?', 'Svizzera|Belgio|Stati Uniti|Messico', 'Daniel Peter usò il latte in polvere prodotto dal suo vicino, Henri Nestlé.'],
    ['Quale dolce prende il nome da una ballerina russa?', 'La pavlova|Il tiramisù|La crème brûlée|La tarte Tatin', 'Australia e Nuova Zelanda sostengono entrambe di averla creata per la tournée di Anna Pavlova negli anni Venti.'],
    ['La pesca Melba prende il nome da chi?', 'Da una cantante lirica|Da una ballerina|Da una regina|Dalla moglie di un cuoco', 'Auguste Escoffier la creò per il soprano australiano Nellie Melba negli anni Novanta dell’Ottocento.'],
    ['Perché le caramelle alla menta gettate nella cola la fanno eruttare?', 'La loro superficie ruvida fa formare le bolle in fretta|Reagiscono come un acido|Contengono bicarbonato|La scaldano', 'Le minuscole cavità della caramella danno al gas milioni di punti in cui formare bolle tutte insieme.'],
    ['Che cosa rende alcuni tuorli più arancioni di altri?', 'Il cibo della gallina|La razza della gallina|La stagione|Il colore del guscio', 'Le galline nutrite con mais o petali di calendula fanno tuorli più scuri.'],
    ['Che differenza c’è tra uova marroni e uova bianche?', 'Solo la razza della gallina|Le marroni sono più sane|Le bianche sono sbiancate|Le marroni sono più vecchie', 'Dentro sono uguali. Le razze con i lobi delle orecchie bianchi spesso fanno uova bianche.'],
    ['Di che cosa sono fatti soprattutto i bastoncini di surimi?', 'Pesce bianco|Polpa di granchio|Alghe|Tofu', 'Il merluzzo d’Alaska viene ridotto in una pasta chiamata surimi, poi aromatizzato e colorato per sembrare granchio.'],
    ['Quale paese ha inventato i noodles istantanei?', 'Il Giappone|La Cina|La Corea del Sud|Gli Stati Uniti', 'Li creò Momofuku Ando nel 1958, e i noodles in tazza nel 1971.'],
    ['Che cos’è il jollof?', 'Un piatto di riso dell’Africa occidentale|Una bevanda giamaicana|Un ballo brasiliano|Un dolce turco', 'Nigeria e Ghana hanno una famosa rivalità amichevole su chi lo fa meglio.'],
    ['Che cos’è la poutine canadese?', 'Patatine con formaggio fresco a pezzetti e sugo|Una frittella all’acero|Una zuppa di pesce|Una minestra di piselli', 'Viene dal Québec, dove il formaggio freschissimo cigola sotto i denti.'],
    ['Il rabarbaro è un frutto o un ortaggio?', 'Un ortaggio, ma per la legge americana è un frutto|Una bacca|Frutta secca|Un’erba', 'Nel 1947 un tribunale di New York lo dichiarò frutto per abbassare i dazi d’importazione. Le sue foglie sono velenose.'],
    ['Quale tribunale ha stabilito che i pomodori sono ortaggi?', 'La Corte Suprema degli Stati Uniti|L’Unione europea|Le Nazioni Unite|Il parlamento italiano', 'Nel 1893, per motivi fiscali, anche se botanicamente sono frutti.'],
    ['Che cosa rende lucide le caramelle gommose a fagiolino (jelly beans)?', 'Una glassa prodotta da insetti|Solo cera d’api|Olio|Acqua e zucchero', 'La glassa da pasticceria è gommalacca, una resina prodotta dalla cocciniglia della lacca.'],
    ['Quale colorante alimentare rosso si ricava da insetti schiacciati?', 'Il carminio|La paprica|Il rosso di barbabietola|Lo zafferano', 'Le cocciniglie danno il carminio, usato in alcuni yogurt, dolciumi e rossetti.'],
    ['In quale paese sono stati inventati gli orsetti gommosi?', 'Germania|Stati Uniti|Belgio|Svizzera', 'Hans Riegel creò i suoi «orsetti ballerini» a Bonn nel 1922.'],
    ['Come si misurò per la prima volta, nel 1912, la piccantezza dei peperoncini?', 'Lo assaggiavano diluito finché non bruciava più|Con un termometro|Contando i semi|Con la cartina al tornasole', 'Il metodo di Wilbur Scoville ci ha dato le unità Scoville. Oggi le sostanze si misurano con le macchine.'],
    ['Come trasformano le api il nettare in miele?', 'Se lo passano di bocca in bocca e lo asciugano con le ali|Ci masticano dentro il polline|Lo mescolano con la cera|Lo tengono nelle zampe', 'Gli enzimi delle api scompongono gli zuccheri, e la ventilazione fa evaporare quasi tutta l’acqua.'],
    ['Perché sulle navi da carico i pistacchi sono considerati un pericolo?', 'I grossi mucchi possono scaldarsi e prendere fuoco da soli|Attirano i ratti|Esplodono se si bagnano|Sono troppo pesanti', 'L’alto contenuto di grassi può far autoriscaldare il carico sfuso.'],
    ['La ricetta più antica conosciuta della torta di mele viene da quale paese?', 'Inghilterra|Stati Uniti|Francia|Paesi Bassi', 'È del 1381 e non ha zucchero, che costava troppo. Al suo posto, fichi, uvetta e pere.'],
    ['Nella Seconda guerra mondiale la Marina americana costruì una fabbrica galleggiante di che cosa?', 'Di gelato|Di pane|Di pizza|Di ciambelle', 'Una chiatta di cemento fu trainata per il Pacifico per tirare su il morale dei marinai.'],
    ['Quale prelibatezza mangiavano i ricchi dell’antica Roma?', 'Lingue di fenicottero|Uova di serpente|Piume di pavone|Marmellata di formiche', 'Autori come Plinio le citano come leccornia per i più ricchi.'],
    ['Una banca italiana accetta come garanzia per i prestiti che cosa?', 'Forme di Parmigiano Reggiano|Bottiglie d’olio d’oliva|Tartufi|Sacchi di pasta', 'Il Credem tiene centinaia di migliaia di forme a stagionare nei suoi magazzini climatizzati.'],
    ['Quale ingrediente improbabile è stato usato per aromatizzare alcuni cibi alla vaniglia e al lampone?', 'Una secrezione delle ghiandole odorose del castoro|Alghe|Corteccia d’albero|Olio di pesce', 'Si chiama castoreum. È sicuro, ma raro e costoso, quindi oggi nei cibi non si usa quasi più.'],
    ['Quali animali non sentono il bruciore del peperoncino?', 'Gli uccelli|I gatti|I maiali|I cani', 'Alla pianta conviene: gli uccelli inghiottono i semi interi e li spargono lontano.'],
    ['Nei bui «forcing sheds» dello Yorkshire, quale pianta si sente crescere?', 'Il rabarbaro|Il bambù|L’asparago|Il mais', 'Al buio cresce così in fretta che i germogli scricchiolano e schioccano.'],
    ['Il garum, la salsa preferita dei romani, era fatto con che cosa?', 'Interiora di pesce lasciate fermentare al sole|Uva marcia|Bava di lumaca|Noccioli d’oliva', 'Le fabbriche che lo producevano stavano spesso fuori città, per via della puzza.'],
    ['Secondo la leggenda aziendale, come diventò un successo la salsa Worcestershire?', 'Una partita venuta male fu dimenticata in cantina per anni|Un cuoco reale ci rovesciò dello zucchero|Una nave che la trasportava prese fuoco|Un medico la prescrisse', 'Pare che il primo tentativo di Lea e Perrins fosse disgustoso, finché non lo riassaggiarono molto tempo dopo.'],
    ['Prima del Cinquecento, la cucina indiana e quella thailandese non avevano che cosa?', 'Il peperoncino|Il riso|L’aglio|Lo zenzero', 'Il peperoncino arrivò dalle Americhe con i mercanti portoghesi. Prima, il piccante lo dava il pepe nero.'],
    ['Nel 1991 un tribunale fiscale britannico dovette decidere se i Jaffa Cakes fossero che cosa?', 'Torte o biscotti|Dolciumi o medicine|Cibo o giocattoli|Frutta o verdura', 'Furono dichiarati torte, anche perché quando sono vecchi diventano duri, come le torte. I biscotti invece si ammorbidiscono.'],
    ['Che cosa portò di nascosto nello spazio l’astronauta John Young nel 1965?', 'Un panino con la carne in scatola|Un pesce rosso|Un’armonica|Un topolino', 'Lo passò al compagno in pieno volo. Le briciole potevano finire nei comandi, e il Congresso non la prese bene.'],
    ['Perché la gomma da masticare da palloncini di solito è rosa?', 'Il rosa era l’unico colorante che aveva l’inventore|Rosa ha un sapore migliore|Era fatta con le fragole|L’ha scelto un sondaggio', 'Walter Diemer la creò nel 1928 e prese il colore che aveva sottomano.'],
    ['Perché nel 1985 l’Italia vietò i maiali nella ricerca dei tartufi?', 'Scavavano il terreno e si mangiavano i tartufi|Erano troppo lenti|Non sentivano l’odore dei tartufi|I tartufi li facevano star male', 'Ai maiali i tartufi piacciono quanto a noi. Oggi a fiutare sono quasi sempre i cani.'],
    ['Nel 1511 il caffè fu vietato per breve tempo in quale città?', 'La Mecca|Parigi|Londra|Vienna', 'Il governatore temeva che i caffè favorissero pettegolezzi e rivolte. Il divieto non durò.'],
    ['Quale presidente americano fece arrivare caramelle jelly beans a tonnellate per il suo insediamento nel 1981?', 'Ronald Reagan|Richard Nixon|John F. Kennedy|Bill Clinton', 'Aveva cominciato a mangiarle per smettere di fumare la pipa. Fu creato un gusto al mirtillo per avere il rosso, il bianco e il blu.'],
  ],
  geo: [
    ['Qual è il posto più secco della Terra, poli esclusi?', 'Il deserto di Atacama|Il Sahara|La Valle della Morte|Il Gobi', 'Alcune stazioni meteo lì non hanno mai registrato una goccia di pioggia.'],
    ['Qual è il centro abitato tutto l’anno più freddo del mondo?', 'Ojmjakon, in Russia|Reykjavík, in Islanda|Oslo, in Norvegia|Anchorage, negli Stati Uniti', 'Ha toccato −67,7 °C. Le scuole chiudono solo quando si scende sotto i −50 °C circa.'],
    ['Quali due paesi confinano con più stati, 14 a testa?', 'Cina e Russia|Brasile e Argentina|Germania e Francia|India e Pakistan', 'Entrambi hanno confini di terra con 14 vicini.'],
    ['Qual è la capitale della Svizzera?', 'Berna|Zurigo|Ginevra|Basilea', 'Ufficialmente la Svizzera non ha una capitale. Berna è chiamata «città federale».'],
    ['Qual è il paese più piatto del mondo?', 'Le Maldive|I Paesi Bassi|La Danimarca|Il Qatar', 'Il suo punto naturale più alto è a circa 2,4 m sul livello del mare.'],
    ['Quale paese ha circa cinque pecore per ogni abitante?', 'La Nuova Zelanda|L’Australia|L’Irlanda|L’Islanda', 'All’inizio degli anni Ottanta il rapporto era di oltre 20 a 1.'],
    ['La bandiera di quale paese mostra un fucile AK-47?', 'Mozambico|Guatemala|Haiti|Kenya', 'È incrociato con una zappa, sopra un libro aperto.'],
    ['Quale paese ha sulla bandiera la propria cartina?', 'Cipro|Malta|Giappone|Cile', 'Anche la bandiera del Kosovo mostra il suo profilo.'],
    ['Qual è l’unica bandiera nazionale con un disegno diverso su ciascun lato?', 'Quella del Paraguay|Quella dell’Arabia Saudita|Quella del Cile|Quella del Perù', 'Il davanti mostra lo stemma nazionale, il retro il sigillo del Tesoro.'],
    ['Quali due paesi hanno bandiere quasi identiche?', 'Ciad e Romania|Giappone e Bangladesh|Italia e Irlanda|Perù e Canada', 'I blu sono appena diversi. Anche le bandiere di Monaco e dell’Indonesia sono quasi gemelle.'],
    ['Le cascate del Niagara sono già state «spente». Vero o falso?', 'Vero|Falso', 'Nel 1969 gli ingegneri sbarrarono le Cascate americane per mesi per studiare l’erosione.'],
    ['Qual è la catena montuosa più lunga della Terra?', 'La dorsale medio-oceanica, sotto il mare|Le Ande|L’Himalaya|Gli Urali', 'Più di 60.000 km di montagne quasi tutte sommerse, che si snodano intorno al globo.'],
    ['Qual è la montagna più alta d’Europa?', 'L’Elbrus|Il Monte Bianco|Il Cervino|Il Musala', 'È alto 5.642 m, nel Caucaso russo. Il Monte Bianco è il più alto delle Alpi.'],
    ['Dove si trova la terraferma più bassa della Terra?', 'Sulla riva del Mar Morto|Nella Valle della Morte|Nei Paesi Bassi|Sulla costa del Caspio', 'Circa 430 m sotto il livello del mare, e scende man mano che il mare si ritira.'],
    ['Qual è la strada più lunga del mondo?', 'La Panamericana|La Route 66|La Via della Seta|La Trans-Canada Highway', 'Circa 30.000 km dall’Alaska all’Argentina, interrotti solo dalla giungla del Darién.'],
    ['Una città di quale paese nel 1950 cambiò nome in onore di un quiz radiofonico?', 'Stati Uniti|Canada|Australia|Irlanda', 'Hot Springs, nel New Mexico, diventò Truth or Consequences.'],
    ['Y, uno dei nomi di luogo più corti del mondo, è un villaggio di quale paese?', 'Francia|Norvegia|Galles|Giappone', 'I suoi abitanti si chiamano Ypsiloniens.'],
    ['Quale di questi paesi non ha sbocco sul mare?', 'La Bolivia|Il Perù', 'La Bolivia perse la costa in una guerra con il Cile negli anni Ottanta dell’Ottocento, ma ha ancora una marina militare sul lago Titicaca.'],
    ['Quali due paesi sono «doppiamente senza sbocco sul mare»?', 'Liechtenstein e Uzbekistan|Svizzera e Austria|Nepal e Bhutan|Ciad e Niger', 'Da entrambi bisogna attraversare almeno due confini per arrivare al mare.'],
    ['Quale paese è completamente circondato dal Sudafrica?', 'Il Lesotho|L’eSwatini|Il Botswana|La Namibia', 'Sta tutto sopra i 1.000 m: è il paese con il «punto più basso» più alto del mondo.'],
    ['Quali due paesi condividono una biblioteca con il confine dipinto sul pavimento?', 'Stati Uniti e Canada|Francia e Spagna|Belgio e Paesi Bassi|Germania e Austria', 'Nella Haskell Library una riga nera segna dove finisce il Vermont e comincia il Québec.'],
    ['Nella cittadina di Baarle, che cosa passa proprio in mezzo a case e caffè?', 'Il confine tra Belgio e Paesi Bassi|Un fiume|Una ferrovia|L’Equatore', 'Una casa è belga o olandese a seconda di dove si trova la porta d’ingresso.'],
    ['In quale paese si trova Son Doong, la galleria di grotta più grande che si conosca?', 'Vietnam|Cina|Messico|Slovenia', 'Dentro ha una sua giungla e le sue nuvole, e nella sala più grande ci starebbe un palazzo di 40 piani.'],
    ['Dove si incrociano l’Equatore e il meridiano di Greenwich?', 'In mare, al largo dell’Africa occidentale|A Londra|In Ecuador|Al Polo Nord', 'I cartografi per scherzo lo chiamano «Null Island», l’isola che non c’è.'],
    ['Quale paese prende il nome da un albero?', 'Il Brasile|Il Libano|Il Canada|Il Perù', 'Il legno di brasile dava una tintura rossa molto apprezzata in Europa.'],
    ['Che cosa significa in origine «Canada»?', 'Villaggio|Grande terra|Il nord|Acero', 'Dalla parola irochese kanata, villaggio o insediamento.'],
    ['Nihon, il nome con cui il Giappone chiama se stesso, che cosa significa?', 'Origine del sole|Terra di isole|Popolo delle montagne|Onda che sale', 'Da qui viene «Paese del Sol Levante».'],
    ['Che cosa significa probabilmente «Mississippi»?', 'Grande fiume|Acqua fangosa|Grande serpente|Lunga valle', 'Viene da un nome ojibwe. Insieme al Missouri forma uno dei sistemi fluviali più lunghi del mondo.'],
    ['Quando è stato verde l’ultima volta il Sahara, con laghi e praterie?', 'Circa 6.000 anni fa|Mai|Circa 6 milioni di anni fa|Circa 600 anni fa', 'Le pitture rupestri mostrano giraffe, ippopotami e persone che nuotano.'],
    ['Quale lago è quasi sparito dopo che i fiumi che lo alimentavano sono stati prosciugati?', 'Il lago d’Aral|Il Mar Morto|Il lago Bajkal|Il lago Titicaca', 'Un tempo era uno dei quattro laghi più grandi del mondo; ha perso quasi tutta l’acqua dopo l’irrigazione sovietica dagli anni Sessanta.'],
    ['Che cosa significa «-stan», come in Kazakistan?', 'Terra di|Fiume|Montagna|Popolo', 'Viene dal persiano: Afghanistan vuol dire terra degli afghani.'],
    ['Il lago Hillier, in Australia, è famoso per essere di che colore?', 'Rosa acceso|Nero|Verde acceso|Bianco latte', 'Il colore lo danno alghe e batteri che amano il sale. Sembra rosa perfino in un bicchiere.'],
    ['Su quale isola crescono gli alberi «sangue di drago» a forma di ombrello?', 'Socotra|Madagascar|Tasmania|Bali', 'Circa un terzo delle piante di Socotra non cresce in nessun’altra parte della Terra.'],
    ['In quale altro posto vive circa il 90% delle piante e degli animali del Madagascar?', 'In nessun altro posto|In Africa|In India|In Australia', 'Tutti i lemuri selvatici del mondo vivono solo lì.'],
    ['Quale città è più a nord?', 'Londra|Calgary', 'Londra è a circa 51,5° N, Calgary a circa 51,0° N, eppure gli inverni di Londra sono molto più miti.'],
    ['Quale città è più a est?', 'Il Cairo|Istanbul', 'Il Cairo è a circa 31° E, Istanbul a circa 29° E.'],
    ['Se scavassi dritto attraverso la Terra partendo dalla Spagna, dove usciresti?', 'In Nuova Zelanda|In Cina|In Australia|In Argentina', 'Quasi tutte le terre hanno l’oceano dalla parte opposta. Spagna e Nuova Zelanda sono una rara coppia.'],
    ['Nel punto più vicino, quanto distano la Russia e gli Stati Uniti?', 'Circa 4 km|Circa 40 km|Circa 400 km|Circa 4.000 km', 'La Grande Diomede (Russia) e la Piccola Diomede (Stati Uniti) stanno nello stretto di Bering, ai due lati della linea del cambiamento di data: 21 ore di differenza.'],
    ['Quale stato americano è sia il più a ovest sia il più a est?', 'L’Alaska|Le Hawaii|Il Maine|La Florida', 'Alcune isole Aleutine si trovano appena oltre il meridiano 180°, nell’emisfero orientale.'],
    ['Che cosa è più grande: il Principato di Monaco o il Central Park di New York?', 'Central Park|Monaco', 'Monaco misura circa 2,1 km², Central Park circa 3,4 km².'],
    ['Con quale paese la Francia ha il confine di terra più lungo?', 'Il Brasile|La Spagna|Il Belgio|La Germania', 'Grazie alla Guyana francese, il confine corre per circa 730 km nell’Amazzonia.'],
    ['Quale capitale non ha semafori?', 'Thimphu, in Bhutan|Reykjavík, in Islanda|Monaco|Vaduz, in Liechtenstein', 'Negli anni Novanta ne provarono uno, ma la gente preferiva i vigili che dirigono il traffico a mano.'],
    ['Quale minuscolo paese si è offerto in affitto su Airbnb?', 'Il Liechtenstein|Andorra|San Marino|Monaco', 'Nel 2011, per circa 70.000 dollari a notte, con cartelli stradali personalizzati compresi.'],
    ['Perché le Blood Falls, le «cascate di sangue» dell’Antartide, sono rosse?', 'Acqua salata e ferrosa che all’aria arrugginisce|Alghe rosse|Sangue di pinguino|Rocce rosse', 'L’acqua viene da un lago rimasto sigillato sotto il ghiacciaio per più di un milione di anni.'],
    ['Quale paese ha più cavalli che abitanti?', 'La Mongolia|Il Kazakistan|L’Irlanda|L’Argentina', 'Milioni di cavalli, più dei suoi circa 3,5 milioni di abitanti, anche dopo gli inverni più duri.'],
    ['Qual è l’unico paese che sta in tutti e quattro gli emisferi?', 'Kiribati|L’Indonesia|L’Ecuador|Il Brasile', 'Le sue isole stanno a cavallo sia dell’Equatore sia del meridiano 180°.'],
    ['In quale direzione si trova il Canada rispetto al centro di Detroit?', 'A sud|A nord|A est|A ovest', 'Windsor, in Ontario, è appena al di là del fiume, verso sud.'],
    ['Che cosa sostiene gran parte di Venezia?', 'Milioni di pali di legno piantati nel fango|Zattere galleggianti|Pilastri di cemento|Trampoli d’acciaio', 'Sott’acqua, senza ossigeno, il legno resiste da secoli.'],
    ['Quale paese usa un calendario di 13 mesi?', 'L’Etiopia|L’Egitto|L’Iran|Il Nepal', 'Dodici mesi di 30 giorni, più uno di 5 o 6. È indietro di circa 7–8 anni rispetto al calendario occidentale.'],
    ['Nel villaggio olandese di Giethoorn, come ci si sposta di solito?', 'In barca|In funivia|A cavallo|Con gli sci', 'I canali prendono il posto delle strade, con circa 180 ponticelli.'],
    ['Le Hawaii si stanno avvicinando lentamente a quale paese?', 'Al Giappone|Al Messico|All’Australia|Al Cile', 'La placca pacifica le porta verso nord-ovest di alcuni centimetri all’anno.'],
    ['Il volo di linea più breve del mondo, tra due isole scozzesi, può durare quanto?', 'Meno di un minuto|Circa 20 minuti|Circa un’ora|Circa 10 minuti', 'Il salto tra Westray e Papa Westray, nelle Orcadi, è di circa 2,7 km. Il record è di 53 secondi.'],
    ['Una mattina presto del 1967, tutta la Svezia fece che cosa?', 'Passò alla guida a destra|Cambiò moneta|Rinominò la capitale|Spostò indietro gli orologi per sempre', 'Nel «giorno H» il traffico si fermò prima delle 5 del mattino, poi cambiò lato con molta attenzione.'],
    ['Nel 2011, quale paese saltò un giorno intero?', 'Samoa|Il Giappone|Le Figi|La Nuova Zelanda', 'Passò dal 29 al 31 dicembre spostandosi dall’altra parte della linea del cambiamento di data, più vicino nel tempo ai suoi partner commerciali.'],
    ['Quale albergo svedese viene ricostruito da zero ogni inverno?', 'L’Icehotel|Un albergo sugli alberi|Un albergo sott’acqua|Un albergo su un treno', 'Le sue stanze stagionali sono scolpite nel ghiaccio del fiume Torne e ogni primavera si sciolgono di nuovo nel fiume.'],
    ['Nella zona della baia di Hudson, in Canada, che cosa è un po’ più debole che nel resto della Terra?', 'La gravità|La luce del sole|Il vento|I segnali radio', 'Il terreno si sta ancora sollevando dopo il peso dei ghiacciai dell’era glaciale, e la roccia in profondità è meno densa.'],
  ],
  space: [
    ['La luna Titano, con i suoi laghi di metano liquido, appartiene a quale pianeta?', 'Saturno|Giove|Nettuno|Marte', 'Titano è l’unica luna con un’atmosfera densa. La sonda Huygens ci è atterrata nel 2005.'],
    ['Qual è la luna più grande del sistema solare?', 'Ganimede|Titano|La nostra Luna|Europa', 'Ganimede, luna di Giove, è più grande del pianeta Mercurio.'],
    ['Quale luna è il posto più vulcanico del sistema solare?', 'Io|Europa|Callisto|Titano', 'Io, luna di Giove, ha centinaia di vulcani attivi.'],
    ['Che cosa ha probabilmente Europa, luna di Giove, sotto la crosta di ghiaccio?', 'Un oceano salato|Un mare di ferro fuso|Delle foreste|Niente di niente', 'Potrebbe contenere circa il doppio dell’acqua di tutti gli oceani della Terra.'],
    ['Quanti pianeti del sistema solare hanno gli anelli?', 'Quattro|Uno|Due|Otto', 'Quelli di Saturno sono i più luminosi, ma anche Giove, Urano e Nettuno hanno anelli deboli.'],
    ['Quasi ovunque, quanto sono spessi gli anelli di Saturno?', 'Circa 10 metri|Circa 1.000 km|Circa 1 cm|Circa 100.000 km', 'Sono larghi centinaia di migliaia di chilometri, ma in alcuni punti più sottili di un palazzo.'],
    ['Quanto è forte la gravità a bordo della Stazione spaziale internazionale?', 'Circa il 90% di quella terrestre|Zero|Circa il 10%|Più forte che sulla Terra', 'Gli astronauti galleggiano perché stanno continuamente cadendo intorno alla Terra.'],
    ['Perché gli astronauti nello spazio non riescono a piangere davvero?', 'Le lacrime non cadono: restano attaccate all’occhio|Gli occhi si seccano|Il casco lo impedisce|Lassù non ci si sente tristi', 'Chris Hadfield ha mostrato che le lacrime formano una pallina tremolante sull’occhio.'],
    ['Oltre al vulcano più alto, che cos’altro ha Marte?', 'Il canyon più grande del sistema solare|Un oceano|Gli anelli|Un’atmosfera respirabile', 'La Valles Marineris è lunga circa 4.000 km, quanto sono larghi gli Stati Uniti.'],
    ['Quale rover marziano, costruito per durare 90 giorni, andò avanti per 14 anni?', 'Opportunity|Curiosity|Perseverance|Sojourner', 'Il suo ultimo messaggio, come lo hanno parafrasato i fan: «La mia batteria è scarica e si sta facendo buio.»'],
    ['Che cosa ha volato su Marte nel 2021?', 'Un piccolo elicottero|Un pallone|Un aeroplanino di carta|Un drone a forma di uccello', 'Ingenuity è stato il primo velivolo a motore su un altro pianeta. Ha fatto 72 voli.'],
    ['Di che colore è il cielo sulla Luna di giorno?', 'Nero|Azzurro|Grigio|Arancione', 'Senza aria che diffonda la luce del sole, il cielo resta nero anche quando il Sole è alto.'],
    ['La Luna ha un lato oscuro che non vede mai la luce del sole?', 'No, ogni lato riceve la luce del sole|Sì|Solo d’inverno|Solo un anno sì e uno no', 'C’è una faccia nascosta che dalla Terra non vediamo mai, ma riceve tanta luce quanto quella visibile.'],
    ['Da dove viene, con ogni probabilità, la Luna?', 'Da un gigantesco scontro con la giovane Terra|Fu catturata mentre passava|Si staccò da una cometa|Viene da Marte', 'Un corpo grande come Marte, chiamato Theia, colpì probabilmente la Terra circa 4,5 miliardi di anni fa.'],
    ['Quanto impiega la luce del nucleo del Sole ad arrivare alla sua superficie?', 'Migliaia di anni o più|8 minuti|1 secondo|1 giorno', 'Rimbalza così tanto all’interno che le stime vanno da circa 10.000 a 170.000 anni.'],
    ['Si può vedere un’altra galassia a occhio nudo?', 'Sì|No', 'Andromeda, a circa 2,5 milioni di anni luce, dai posti bui si vede come una macchiolina sbiadita.'],
    ['Quante stelle si possono vedere in una notte limpida e buia?', 'Qualche migliaio|Qualche centinaio|Circa un milione|Circa un miliardo', 'In tutto il cielo ce ne sono circa 9.000 abbastanza luminose, ma solo metà alla volta sta sopra l’orizzonte.'],
    ['A che velocità viaggia la Terra intorno al Sole?', 'Circa 107.000 km/h|Circa 1.000 km/h|Circa 10 km/h|Circa 1 milione di km/h', 'Circa 30 km ogni secondo.'],
    ['A che velocità gira il suolo all’Equatore intorno all’asse terrestre?', 'Circa 1.670 km/h|Circa 100 km/h|Circa 10.000 km/h|Non si muove', 'Non lo senti perché tutto intorno a te si muove alla stessa velocità.'],
    ['Quanto impiega la Terra a fare un giro su se stessa, misurato rispetto alle stelle?', 'Circa 23 ore e 56 minuti|Esattamente 24 ore|25 ore|24 ore e 4 minuti', 'I quattro minuti in più riportano il Sole nello stesso punto del cielo.'],
    ['Quale di questi anni NON è stato bisestile?', '1900|2000|2024|1996', 'Gli anni di fine secolo sono bisestili solo se divisibili per 400: il 2000 lo era, il 1900 no.'],
    ['Chi fece la prima passeggiata spaziale?', 'Aleksej Leonov|Jurij Gagarin|Neil Armstrong|John Glenn', 'Nel 1965 la tuta gli si gonfiò così tanto che dovette far uscire aria per riuscire a rientrare.'],
    ['Quanto tempo passarono Armstrong e Aldrin a camminare sulla Luna?', 'Circa due ore e mezza|Circa 2 giorni|Circa 10 minuti|Circa 2 settimane', 'Gli equipaggi successivi restarono di più: quello dell’Apollo 17 passò fuori più di 22 ore.'],
    ['Che cosa diventa più caldo: la superficie della Luna a mezzogiorno o un bollitore che bolle?', 'La superficie della Luna|Il bollitore', 'Circa 120 °C al sole, che scendono a circa −170 °C di notte.'],
    ['Quanto dura un giorno sulla Luna, da un’alba all’altra?', 'Circa 29,5 giorni terrestri|24 ore|Circa un anno|Circa 3 giorni', 'Quindi quasi ovunque ci sono circa due settimane di luce e poi due settimane di notte.'],
    ['Quale sonda è stata la prima ad attraversare l’atmosfera esterna del Sole?', 'La Parker Solar Probe|Voyager 1|Hubble|Juno', 'Ci è riuscita nel 2021, ed è l’oggetto più veloce mai costruito.'],
    ['Che cosa andò storto al telescopio Hubble dopo il lancio?', 'Lo specchio aveva una forma leggermente sbagliata|Non aveva la fotocamera|Puntava verso la Terra|Era troppo pesante', 'L’errore era di circa un cinquantesimo dello spessore di un capello. Nel 1993 gli astronauti montarono un’ottica correttiva.'],
    ['Su quale pianeta è stata registrata la temperatura più fredda?', 'Urano|Nettuno|Saturno|Marte', 'Nettuno è più lontano, ma Urano è sceso a circa −224 °C.'],
    ['La cometa di Halley torna più o meno ogni quanti anni?', '76|10|200|1.000', 'Mark Twain nacque quando passò nel 1835 e morì il giorno dopo il suo ritorno, nel 1910.'],
    ['In quale direzione punta la coda di una cometa?', 'Lontano dal Sole|Dietro la cometa|Verso il Sole|Dritta verso il basso', 'La spinge il vento solare, quindi la coda può perfino andare avanti quando la cometa si allontana.'],
    ['Di che cosa è fatta soprattutto la fascia degli asteroidi?', 'Di spazio vuoto|Di rocce ammassate|Di gas|Di ghiaccio', 'Le rocce sono così distanti tra loro che le sonde la attraversano senza problemi.'],
    ['Che cosa avvistò la sonda New Horizons su Plutone nel 2015?', 'Una pianura di ghiaccio a forma di cuore|Degli anelli|Oceani d’acqua|Una luna più grande di lui', 'La regione luminosa è fatta in parte di azoto ghiacciato.'],
    ['Quale pianeta fu trovato con la matematica prima che qualcuno lo vedesse?', 'Nettuno|Urano|Saturno|Plutone', 'Gli astronomi calcolarono dove doveva essere dalle spinte sull’orbita di un altro pianeta, e lo trovarono nel 1846.'],
    ['Quale pianeta fu il primo a essere scoperto con il telescopio?', 'Urano|Nettuno|Plutone|Saturno', 'William Herschel lo avvistò nel 1781 e voleva chiamarlo come re Giorgio III.'],
    ['Quale paese è stato il primo ad atterrare sulla faccia nascosta della Luna?', 'La Cina|Gli Stati Uniti|La Russia|L’India', 'Chang’e 4 è atterrata nel 2019 e ha liberato un piccolo rover.'],
    ['Quale paese è stato il primo ad atterrare vicino al polo sud della Luna?', 'L’India|Gli Stati Uniti|La Cina|Il Giappone', 'Chandrayaan-3 è atterrata ad agosto 2023.'],
    ['In media, quanto è lontana la Luna?', 'Circa 384.000 km|Circa 38.000 km|Circa 3,8 milioni di km|Circa 3.800 km', 'Tutti gli altri pianeti, messi uno accanto all’altro, ci starebbero più o meno giusti in mezzo.'],
    ['Che cosa è più grande: il Sole o la supergigante rossa Betelgeuse?', 'Betelgeuse|Il Sole', 'Messa al posto del Sole, arriverebbe oltre l’orbita di Marte.'],
    ['Che cosa ti succederebbe nello spazio senza tuta?', 'Sveniresti in circa 15 secondi, ma non esploderesti|Esploderesti|Gelaresti all’istante|Evaporeresti', 'In un test della NASA del 1966 la tuta di un uomo perse aria in una camera a vuoto. Restò cosciente circa 14 secondi e sopravvisse.'],
    ['Da dove viene probabilmente gran parte dell’oro della Terra?', 'Da scontri tra stelle morte|Dal nucleo terrestre|Dai vulcani|Dai batteri', 'Nel 2017 gli astronomi hanno visto fondersi due stelle di neutroni e formarsi elementi pesanti.'],
    ['Sulla Luna ci sono i terremoti?', 'Sì, i «lunamoti»|No, mai', 'Li registrarono i sismometri dell’Apollo. Alcuni durarono più di 10 minuti, perché la Luna, secca, risuona come una campana.'],
    ['Perché gli astronauti cercano di non ruttare nello spazio?', 'Cibo e gas non si separano: col rutto viene su il vomito|Rimbomba nella stazione|È vietato dal regolamento|Fa scattare gli allarmi', 'Senza gravità il gas non sale in cima allo stomaco. Gli astronauti lo chiamano «rutto bagnato».'],
    ['Durante la prima passeggiata spaziale americana, nel 1965, che cosa volò via?', 'Un guanto di scorta|Una macchina fotografica|Una chiave inglese|Un casco', 'Restò in orbita per circa un mese prima di bruciare. Da allora gli astronauti hanno perso anche una borsa degli attrezzi e una spatola.'],
    ['Pur essendo il più vicino al Sole, Mercurio ha che cosa?', 'Ghiaccio nei crateri ai poli|Oceani|Anelli|Una luna', 'Il fondo di quei crateri non vede mai il sole e resta sotto i −170 °C circa.'],
    ['Che cosa sono gli «alberi della Luna»?', 'Alberi nati da semi che hanno girato intorno alla Luna|Alberi piantati sulla Luna|Alberi fossili trovati nelle rocce lunari|Alberi colpiti da meteoriti', 'Nel 1971 l’astronauta dell’Apollo 14 Stuart Roosa portò con sé circa 500 semi. Gli alberi furono piantati in tutti gli Stati Uniti.'],
    ['Secondo gli astronauti dell’Apollo, che odore aveva la polvere lunare?', 'Di polvere da sparo bruciata|Di rose|Di pane tostato bruciato|Di cane bagnato', 'Si attaccava alle tute ed entrava con loro nel modulo lunare.'],
    ['Che cosa fece in silenzio Buzz Aldrin sulla Luna prima di uscire?', 'Fece la comunione|Telefonò alla madre|Mangiò una bistecca|Giocò a scacchi', 'Aveva con sé un minuscolo kit con pane e vino. All’epoca la cosa fu tenuta riservata.'],
    ['Più o meno quanto è costato il nuovo gabinetto spaziale della NASA, mandato in orbita nel 2020?', 'Circa 23 milioni di dollari|Circa 23.000 dollari|Circa 230 dollari|Circa 2,3 miliardi di dollari', 'Era progettato per funzionare meglio per le donne, e l’urina finisce nel riciclo dell’acqua della stazione.'],
    ['Che cosa fu cotto in forno nello spazio per la prima volta, nel 2019?', 'Biscotti con gocce di cioccolato|Pane|Pizza|Una torta di compleanno', 'In un forno speciale, un biscotto ci mise circa due ore. Furono rispediti sulla Terra per essere analizzati, non mangiati.'],
    ['Che cosa schizza fuori da Encelado, luna di Saturno?', 'Getti di ghiaccio d’acqua|Lava|Musica via radio|Tempeste di polvere', 'I geyser al suo polo sud alimentano uno degli anelli di Saturno.'],
    ['Su Mercurio, com’è un giorno rispetto a un anno?', 'Un giorno da un’alba all’altra dura due anni di Mercurio|Un giorno dura un’ora|Sono esattamente uguali|Un anno dura 1.000 giorni', 'Gira lentamente su se stesso mentre corre intorno al Sole: 176 giorni terrestri da un’alba all’altra, 88 per un anno.'],
    ['Quasi tutte le lune di Urano prendono il nome da personaggi di chi?', 'Di Shakespeare e Alexander Pope|Dei miti greci|Dei miti nordici|Della Bibbia', 'Tra queste ci sono Titania, Oberon, Miranda, Puck e Giulietta.'],
    ['Su Titano, luna di Saturno, che cosa potrebbe fare una persona con delle ali legate alle braccia?', 'Volare sbattendole|Nuotare nel terreno|Camminare sulle nuvole|Niente: non c’è aria', 'La sua aria è più densa di quella terrestre, e la gravità è più debole di quella della nostra Luna. Però ci sono circa −180 °C.'],
  ],
  tech: [
    ['Chi chiamò Martin Cooper nel 1973, con la prima telefonata da un cellulare?', 'Un ingegnere di un’azienda rivale|Il presidente degli Stati Uniti|Sua madre|Una pizzeria', 'Chiamò Joel Engel dei Bell Labs da una strada di New York, con in mano un prototipo di oltre 1 kg.'],
    ['Il primo disco rigido di IBM, nel 1956, pesava più o meno quanto?', 'Circa una tonnellata|Circa 1 kg|Circa 10 kg|Circa 100 tonnellate', 'Conteneva circa 5 milioni di caratteri, meno di una canzone in MP3 di oggi.'],
    ['Qual è stata la prima console per videogiochi da collegare alla tv di casa?', 'Magnavox Odyssey|Atari 2600|Nintendo Entertainment System|Sega Master System', 'Uscì nel 1972, senza audio. I giocatori attaccavano allo schermo delle pellicole di plastica per avere i colori.'],
    ['Chi inventò la prima lavastoviglie pratica?', 'Una donna stufa di ritrovarsi le porcellane scheggiate|Il cuoco di un ristorante|Un marinaio|Un idraulico', 'Josephine Cochrane la brevettò nel 1886.'],
    ['Quale di queste cose NON l’ha inventata Thomas Edison?', 'Il telefono|Il fonografo|Una lampadina di lunga durata|Un visore per filmati', 'Alexander Graham Bell brevettò il telefono nel 1876, anche se Edison ne migliorò il microfono.'],
    ['Una lampadina in una caserma dei pompieri della California è accesa da quando?', 'Dal 1901|Dal 1991|Dal 1951|Dal 2001', 'La «Centennial Light» ha una webcam che la tiene d’occhio. La prima webcam si è guastata prima della lampadina.'],
    ['Di che cosa era fatto il primo mouse per computer?', 'Di legno|Di plastica|Di metallo|Di vetro', 'Il mouse di Douglas Engelbart del 1964 era una scatola di legno con due rotelle di metallo.'],
    ['I satelliti GPS devono correggere i loro orologi per che cosa?', 'Per la teoria della relatività di Einstein|Per l’ora legale|Per le eclissi di sole|Solo per i secondi intercalari', 'Senza la correzione, le posizioni sbaglierebbero di circa 10 km al giorno.'],
    ['Di che cosa parlava il primo sito web?', 'Di come funziona il World Wide Web|Di pizze a domicilio|Di un’università|Di gatti', 'Fu messo online al CERN nel 1991 e si può ancora visitare.'],
    ['Quale apparecchio del 1994 viene spesso chiamato il primo smartphone?', 'IBM Simon|BlackBerry|iPhone|Nokia Communicator', 'Aveva touchscreen, email e applicazioni, e la batteria durava circa un’ora.'],
    ['Quale famosa azienda nacque in un garage nel 1939?', 'Hewlett-Packard|Apple|Google|Intel', 'La Disney comprò otto dei suoi primi prodotti, degli oscillatori audio, per il film Fantasia.'],
    ['Quale casa automobilistica cominciò producendo macchine da cucire?', 'Opel|Ford|BMW|Fiat', 'Adam Opel fondò l’azienda nel 1862, poi passò alle biciclette e infine alle auto.'],
    ['Quale casa automobilistica nacque costruendo motori d’aereo?', 'BMW|Toyota|Volvo|Ferrari', 'Il suo marchio bianco e blu viene spesso descritto come un’elica che gira, ma viene dalla bandiera della Baviera.'],
    ['Che cosa produceva all’inizio la famiglia che fondò la Toyota?', 'Telai per tessere|Biciclette|Cuociriso|Radio', 'L’azienda di telai automatici di Sakichi Toyoda costruì la sua prima auto nel 1936.'],
    ['Su che cosa montò all’inizio Honda i suoi piccoli motori?', 'Sulle biciclette|Sugli scooter|Sulle barche|Sui tosaerba', 'Nel 1946 Soichiro Honda usò piccoli motori avanzati dalle radio dell’esercito.'],
    ['Da dove viene il nome Sony?', 'Dal latino sonus, suono, e dall’inglese «sonny», ragazzino|Dal nome di un fondatore|Da una città|Da un fiume', 'I fondatori volevano un nome che funzionasse in qualsiasi lingua.'],
    ['Che cosa vogliono dire le lettere IKEA?', 'Le iniziali di fondatore, fattoria e villaggio|«Casa» in svedese|I nomi di quattro amici|Niente', 'Ingvar Kamprad, Elmtaryd e Agunnaryd. Fondò l’azienda a 17 anni.'],
    ['Il memory foam fu sviluppato all’inizio per che cosa?', 'Per i sedili degli aerei della NASA|Per i letti d’ospedale|Per i materassi|Per le scarpe da corsa', 'Negli anni Sessanta doveva ammortizzare i piloti e migliorare la sicurezza negli incidenti.'],
    ['Qual è stato il primo tweet, nel 2006?', '«just setting up my twttr»|«Hello world»|«Test»|«What’s happening?»', 'Il tweet di Jack Dorsey è stato poi venduto per circa 2,9 milioni di dollari.'],
    ['Che cosa mostrava la prima foto caricata sul web?', 'Un gruppo pop comico di dipendenti del CERN|Un gatto|Un tramonto|Tim Berners-Lee', 'Les Horribles Cernettes, nel 1992.'],
    ['Il primo virus informatico a diffondersi davvero, nel 1982, infettava che cosa?', 'I floppy disk dell’Apple II|Le email|I cellulari|I siti web', 'Elk Cloner, scritto da un quindicenne, mostrava una breve poesia.'],
    ['Quanto ci metteva la prima fotocamera digitale, nel 1975, a salvare una foto?', 'Circa 23 secondi|1 secondo|1 ora|Un giorno', 'Il prototipo Kodak di Steven Sasson pesava circa 3,6 kg e faceva immagini in bianco e nero da 0,01 megapixel.'],
    ['Che cosa pubblicizzava la prima email di spam, nel 1978?', 'Computer|Pillole dimagranti|Vacanze gratis|Una pizzeria', 'Un venditore invitò centinaia di utenti di ARPANET a una dimostrazione di prodotto.'],
    ['Prima delle gomme per cancellare, che cosa si usava per togliere la matita?', 'Il pane|La sabbia|La cera|Il gesso', 'Palline di mollica morbida facevano il lavoro fino agli anni Settanta del Settecento.'],
    ['Da dove viene la parola inglese «rubber», gomma?', 'Dal fatto che cancellava la matita|Da una città brasiliana|Dal nome di un albero|Da uno scienziato', '«To rub» vuol dire strofinare: nel 1770 Joseph Priestley notò che quella resina toglieva le linee di matita.'],
    ['Che cosa successe al primo semaforo, a Londra, nel 1868?', 'Esplose e ferì un poliziotto|Suonava musica|Andava a vapore|Non fu mai acceso', 'Era a gas e stava davanti al Parlamento. Fu tolto presto.'],
    ['Quale paese fu il primo a risolvere un omicidio grazie alle impronte digitali?', 'L’Argentina|Il Regno Unito|Gli Stati Uniti|La Francia', 'Nel 1892 l’impronta insanguinata di un pollice su una porta rivelò l’assassino.'],
    ['Quale giocattolo fu inventato dopo che una molla cadde da uno scaffale e «camminò»?', 'Lo Slinky, la molla saltellante|Lo yo-yo|Il frisbee|Il pupazzo a molla nella scatola', 'L’ingegnere navale Richard James lo vide succedere nel 1943.'],
    ['A che cosa servivano all’inizio le cerniere lampo, negli anni Novanta dell’Ottocento?', 'Per scarpe e stivali|Per i pantaloni|Per le borse|Per le tende', 'Il «clasp locker» di Whitcomb Judson doveva sostituire i bottoni delle scarpe.'],
    ['Perché Walter Hunt inventò la spilla da balia nel 1849?', 'Per pagare un debito|Per il suo bambino|Per l’esercito|Per caso mentre cuciva', 'Vendette il brevetto per 400 dollari, una frazione minuscola di quello che avrebbe fruttato.'],
    ['Dove fu installata la prima scala mobile, nel 1896?', 'Come giostra a Coney Island|Alla Casa Bianca|In una stazione di Londra|Sulla Torre Eiffel', 'L’«ascensore inclinato» di Jesse Reno era un nastro inclinato a scanalature, non una scala.'],
    ['Come dimostrò Elisha Otis che il freno del suo ascensore era sicuro?', 'Tagliò la fune del suo stesso ascensore|Fece cadere una mucca|Scrisse un libro|Lo vendette a poco', 'Lo fece davanti alla folla di una fiera di New York nel 1854, e l’ascensore si fermò.'],
    ['Che cosa trainava i primi treni della metropolitana di Londra nel 1863?', 'Locomotive a vapore|Motori elettrici|Cavalli|Funi', 'Le gallerie si riempivano di fumo, quindi furono costruite poco profonde, con prese d’aria verso la strada.'],
    ['Come era soprannominato il primo telecomando per la tv, nel 1950?', 'Lazy Bones («Pelandrone»)|The Clicker|The Zapper|Couch Buddy', 'Era collegato alla tv con un lungo cavo in cui la gente inciampava di continuo.'],
    ['Come mandavano il segnale molti telecomandi degli anni Cinquanta?', 'Con un clic di ultrasuoni|Con luce infrarossa|Con onde radio|Con un cavo', 'A volte, un mazzo di chiavi agitato poteva cambiare canale per sbaglio.'],
    ['Prima dei frigoriferi, che cosa si comprava per tenere fresco il cibo?', 'Blocchi di ghiaccio|Ghiaccio secco|Neve di montagna|Sabbia fredda', 'D’inverno il ghiaccio si tagliava dai laghi gelati e si spediva fino in India.'],
    ['Prima delle macchine, che cos’era un «computer»?', 'Una persona che faceva calcoli a mano|Una scatola di ottone per contare|Un tipo di orologio|Una scrivania', 'Squadre di «calcolatori» umani, spesso donne, compilavano tabelle per la scienza e per la guerra.'],
    ['Una tecnologia chiave del Wi-Fi è nata da scienziati che cercavano che cosa?', 'Buchi neri che esplodono|Petrolio|Sottomarini|Segnali alieni', 'Il metodo dei radioastronomi australiani per ripulire i segnali pieni di echi fu brevettato negli anni Novanta.'],
    ['La prima persona di cui si sappia uccisa da un veicolo a motore, nel 1869, fu sbalzata da che cosa?', 'Da un’auto a vapore sperimentale|Da un tram a cavalli|Da una bicicletta|Da un treno', 'La scienziata irlandese Mary Ward cadde da una carrozza a vapore costruita dai suoi cugini.'],
    ['Che cosa trasporta circa il 99% dei dati tra un continente e l’altro?', 'Cavi sul fondo del mare|Satelliti|Ripetitori radio|Palloni', 'Sono stati filmati squali che li mordevano, quindi alcuni sono avvolti in materiali extra resistenti.'],
    ['Scrivere le parole contorte dei CAPTCHA un tempo aiutava a fare che cosa?', 'Digitalizzare vecchi libri e giornali|Catturare spie|Contare gli utenti di internet|Addestrare pappagalli', 'reCAPTCHA faceva leggere alle persone le parole che i programmi di scansione non riuscivano a decifrare.'],
    ['Chi ha definito Ctrl+Alt+Canc «un errore»?', 'Bill Gates|Steve Jobs|Mark Zuckerberg|Linus Torvalds', 'Disse che sarebbe stato meglio un solo tasto. La scorciatoia l’ha inventata l’ingegnere IBM David Bradley.'],
    ['Uno dei primi aggeggi comandati via internet, nel 1990, fu che cosa?', 'Un tostapane|Un frigorifero|Una lampada|Una serratura', 'Fu acceso da un computer durante una fiera. Un anno dopo gli aggiunsero una piccola gru robotica per infilare il pane.'],
    ['I codici QR furono inventati nel 1994 per tracciare che cosa?', 'I pezzi delle auto nelle fabbriche|I libri delle biblioteche|I biglietti dei concerti|I pacchi', 'Li progettò un fornitore della Toyota. Lo schema bianco e nero si ispira al gioco da tavolo go.'],
    ['Come era memorizzato il software del computer di guida delle missioni Apollo?', 'In fili intrecciati a mano attraverso minuscoli anelli|Su floppy disk|Su musicassette|Su schede perforate', 'Le operaie, quasi tutte donne, infilavano la «core rope memory»: un filo dentro un anello voleva dire 1, intorno voleva dire 0.'],
    ['Che cosa è venuto prima?', 'L’email|Il World Wide Web', 'L’email risale al 1971. Il web è arrivato circa 20 anni dopo.'],
    ['Il teflon fu scoperto per caso durante ricerche su che cosa?', 'Gas per frigoriferi|Carburante per razzi|Vernice per auto|Gomma da masticare', 'Nel 1938 Roy Plunkett aprì una bombola di gas e ci trovò dentro una polvere bianca scivolosa.'],
    ['Il pacemaker impiantabile nacque dopo che il suo inventore fece che cosa?', 'Montò il pezzo sbagliato in un circuito|Rovesciò il caffè su una radio|Si addormentò in laboratorio|Fece cadere un orologio', 'Wilson Greatbatch notò che, per colpa del suo errore, il circuito pulsava come un battito cardiaco.'],
    ['Che cosa mostrava la prima radiografia di una persona?', 'La mano di una donna con la fede nuziale|Una gamba rotta|Un cranio|Un neonato', 'Wilhelm Röntgen fotografò la mano della moglie nel 1895. Pare che lei abbia detto: «Ho visto la mia morte.»'],
    ['Chi inventò l’aspirapolvere verticale, nel 1907?', 'Un custode asmatico|Una ricca casalinga|Un minatore|Un medico', 'James Spangler vendette il brevetto al marito di sua cugina, William Hoover.'],
  ],
  pop: [
    ['Chi è stato il primo personaggio dei cartoni animati con una stella sulla Walk of Fame di Hollywood?', 'Topolino|Bugs Bunny|Paperino|Picchiarello', 'Topolino ebbe la sua stella nel 1978, per i suoi 50 anni.'],
    ['In E.T., con quali dolcetti Elliott attira l’alieno?', 'I Reese’s Pieces|Gli M&M’s|Le jelly beans|I bottoncini di cioccolato', 'I produttori degli M&M’s rifiutarono l’offerta. Dopo il film le vendite dei Reese’s Pieces volarono.'],
    ['Chi ha vinto più Oscar come attore o attrice?', 'Katharine Hepburn|Meryl Streep|Daniel Day-Lewis|Jack Nicholson', 'Ne ha vinti quattro, tutti come miglior attrice. Meryl Streep ha il record di candidature.'],
    ['Di che cosa è fatta la statuetta dell’Oscar?', 'Bronzo placcato d’oro|Oro massiccio|Argento|Vetro', 'Durante la Seconda guerra mondiale il metallo scarseggiava, e i vincitori ricevevano statuette di gesso dipinto.'],
    ['Qual è stato il primo video di YouTube a raggiungere un miliardo di visualizzazioni?', '«Gangnam Style»|«Despacito»|«Baby Shark Dance»|«Thriller»', 'Nel 2014 mandò in tilt il contatore di YouTube, che dovette essere potenziato.'],
    ['Quanti anni aveva Stevie Wonder quando firmò il suo primo contratto discografico?', '11|18|21|7', 'Il suo primo numero uno arrivò a 13 anni.'],
    ['Perché la casa discografica dei Queen non voleva pubblicare «Bohemian Rhapsody»?', 'Durava quasi sei minuti|C’erano parolacce|Era in latino|Non aveva il ritornello', 'Un amico dj la mise 14 volte in due giorni, e restò al numero uno nel Regno Unito per nove settimane.'],
    ['Quale cantante si chiama in realtà Stefani Germanotta?', 'Lady Gaga|Madonna|Katy Perry|Rihanna', 'Il suo nome d’arte viene dalla canzone dei Queen «Radio Ga Ga».'],
    ['Qual è il vero nome di Elton John?', 'Reginald Dwight|Elton Johnson|Edward John|Robert Davies', 'Si costruì il nome d’arte con quelli di due compagni di band, Elton Dean e Long John Baldry.'],
    ['Quale famoso pittore, secondo la leggenda, vendette un solo quadro in tutta la vita?', 'Vincent van Gogh|Pablo Picasso|Claude Monet|Andy Warhol', 'La storia parla della Vigna rossa. Probabilmente ne vendette o scambiò qualcun altro.'],
    ['Quale opera di Banksy si autodistrusse nel tritadocumenti subito dopo essere stata venduta nel 2018?', 'La bambina con il palloncino|Il lanciatore di fiori|I poliziotti che si baciano|Il poliziotto maleducato', 'Tagliata a metà e ribattezzata «Love is in the Bin», nel 2021 fu rivenduta per circa 18,6 milioni di sterline.'],
    ['Il tabellone originale americano del Monopoly si basa sulle strade di quale città?', 'Atlantic City|New York|Chicago|Las Vegas', 'La versione britannica usa le strade di Londra, con Mayfair come la più cara. Quella italiana ha Parco della Vittoria e Viale dei Giardini.'],
    ['Qual è stato il primo videogioco giocato nello spazio?', 'Tetris|Pong|Space Invaders|Pac-Man', 'Un cosmonauta portò un Game Boy sulla stazione spaziale Mir nel 1993.'],
    ['Che cosa fu usato come sangue nella scena della doccia di Psyco?', 'Sciroppo al cioccolato|Ketchup|Vernice rossa|Succo di ciliegia', 'In bianco e nero, lo sciroppo al cioccolato sembrava più sangue di qualsiasi cosa rossa.'],
    ['Il ruggito del T. rex in Jurassic Park fu costruito in parte con il verso di quale animale?', 'Un cucciolo di elefante|Un gatto|Una balena|Una mucca', 'Il tecnico del suono Gary Rydstrom mescolò un cucciolo di elefante con una tigre e un alligatore.'],
    ['Con che cosa fu creato il ronzio delle spade laser di Guerre stellari?', 'Un vecchio proiettore e un televisore|Un’ape|Una chitarra|Un aspirapolvere', 'Ben Burtt mescolò il motore di un proiettore con il ronzio di una tv captato da un microfono.'],
    ['Chi è stato il primo a interpretare James Bond sullo schermo?', 'Barry Nelson|Sean Connery|Roger Moore|David Niven', 'Fu «Jimmy Bond» nella tv americana nel 1954, otto anni prima del primo film di Sean Connery.'],
    ['In quale paese è nato il Grande Fratello televisivo?', 'Paesi Bassi|Regno Unito|Stati Uniti|Svezia', 'Cominciò nel 1999, e da allora è stato prodotto in più di 60 paesi.'],
    ['Qual è il programma tv per bambini più longevo del mondo?', 'Blue Peter|Sesame Street|Teletubbies|Il trenino Thomas', 'Il programma britannico è iniziato nel 1958.'],
    ['Quale libro è stato tradotto nel maggior numero di lingue, dopo la Bibbia?', 'Il Piccolo Principe|Harry Potter|Pinocchio|Don Chisciotte', 'La storia di Antoine de Saint-Exupéry esiste in più di 500 lingue e dialetti.'],
    ['Quanti editori rifiutarono il primo libro di Harry Potter?', '12|1|50|Nessuno', 'Lo prese Bloomsbury, dopo che la figlia di otto anni del presidente lo aveva adorato.'],
    ['Che lavoro faceva l’autore di Alice nel paese delle meraviglie?', 'Insegnava matematica a Oxford|Il marinaio|Il prete|Il medico', 'Lewis Carroll era lo pseudonimo di Charles Dodgson.'],
    ['Quale autore per ragazzi fu pilota da caccia e poi spia?', 'Roald Dahl|Enid Blyton|Dr. Seuss|C. S. Lewis', 'Dopo aver volato nella Seconda guerra mondiale, lavorò per i servizi segreti britannici a Washington.'],
    ['Quale spettacolo teatrale va in scena a Londra senza interruzioni dal 1952?', 'Trappola per topi|Cats|Les Misérables|Amleto', 'Il giallo di Agatha Christie chiede a ogni pubblico di non rivelare il finale.'],
    ['Quale coppia dei cartoni animati esordì nel 1940 con i nomi Jasper e Jinx?', 'Tom e Jerry|Gatto Silvestro e Titti|Mignolo e Prof|Grattachecca e Fichetto', 'Vinsero poi sette Oscar per il miglior cortometraggio animato.'],
    ['Quale app si chiamava all’inizio Burbn?', 'Instagram|Snapchat|Twitter|TikTok', 'Nacque come app per segnalare dove ti trovavi, con le foto, e cambiò nome nel 2010.'],
    ['Come si chiamava all’inizio Snapchat?', 'Picaboo|SnapIt|Ghosty|Flash', 'La sua mascotte fantasma si chiama Ghostface Chillah.'],
    ['Come si chiamava all’inizio Minecraft?', 'Cave Game|Block World|Craftopia|Mine Town', 'Markus Persson pubblicò la prima versione nel 2009. Microsoft comprò il gioco per 2,5 miliardi di dollari nel 2014.'],
    ['Quale gioco nascondeva il primo famoso «easter egg» dei videogiochi?', 'Adventure, per Atari 2600|Pong|Pac-Man|Tetris', 'Warren Robinett nascose il suo nome in una stanza segreta, perché Atari non citava i suoi programmatori.'],
    ['Perché in Space Invaders gli alieni acceleravano man mano che li abbattevi?', 'Con meno alieni il computer li disegnava più in fretta|Era previsto fin dall’inizio|Un joystick rotto|Puro caso', 'Il creatore tenne l’incidente perché rendeva il gioco molto più emozionante.'],
    ['Qual è il punteggio massimo possibile a Pac-Man?', '3.333.360|999.999|1.000.000|Non c’è limite', 'Una partita perfetta dura circa sei ore e fu giocata per la prima volta nel 1999.'],
    ['Che cosa mostrava un film di 18 secondi del 1896 che scandalizzò il pubblico?', 'Un bacio|Un ballo|Uno starnuto|Una donna che nuotava', 'Il bacio, prodotto dalla compagnia di Edison, fece nascere le prime richieste di censura cinematografica.'],
    ['Che cos’è Nollywood?', 'L’industria cinematografica nigeriana|Uno studio norvegese|Un premio cinematografico|Una catena di cinema', 'È una delle più attive del mondo: produce ben più di mille film all’anno.'],
    ['Quale canzone dei Beatles è tra le più reinterpretate di sempre?', 'Yesterday|Hey Jude|Let It Be|Help!', 'Paul McCartney sognò la melodia e la provava con il testo provvisorio «Scrambled eggs», uova strapazzate.'],
    ['Quale band K-pop ha parlato all’Assemblea generale delle Nazioni Unite?', 'I BTS|Le Blackpink|Gli EXO|Le Twice', 'Fecero un discorso nel 2018 e ci tornarono a parlare nel 2021.'],
    ['Come scriveva Leonardo da Vinci nei suoi taccuini?', 'Al contrario, con la scrittura speculare|In codici numerici segreti|In greco antico|Solo con disegni', 'Gran parte dei suoi scritti va da destra a sinistra. Si leggono con uno specchio.'],
    ['L’album del 1973 di quale band è rimasto più settimane di sempre nella classifica americana Billboard 200?', 'Pink Floyd|The Beatles|Queen|Fleetwood Mac', 'The Dark Side of the Moon ha passato più di 900 settimane in classifica dal 1973.'],
    ['Quale supereroe fu creato da due amici adolescenti, che poi lo vendettero per 130 dollari?', 'Superman|Batman|L’Uomo Ragno|Capitan America', 'Jerry Siegel e Joe Shuster cedettero i diritti nel 1938 per 130 dollari, e poi se ne pentirono.'],
    ['Il mostro di quale film era interpretato nel 1954 da un uomo dentro un costume di gomma?', 'Godzilla|King Kong|Blob|Lo squalo', 'Il costume pesava circa 100 kg, e l’attore Haruo Nakajima sveniva spesso per il caldo.'],
    ['Come chiamava la troupe lo squalo meccanico del film Lo squalo?', 'Bruce|Jeff|Sharky|Big Al', 'Si rompeva di continuo, così Spielberg lo mostrò molto meno, e il film diventò più pauroso.'],
    ['Quali furono le prime parole pronunciate da Topolino, nel 1929?', '«Hot dogs!»|«Hello, everybody!»|«Oh boy!»|«Gee whiz!»', 'Li vendeva a una fiera in The Karnival Kid. A dare la voce a quella prima battuta fu il compositore Carl Stalling.'],
    ['Perché nel 1993 la Disney fermò i lavori su Toy Story?', 'Woody era venuto fuori troppo cattivo|I computer si erano rotti|Tom Hanks aveva lasciato|Una ditta di giocattoli aveva fatto causa', 'I dirigenti avevano chiesto una storia più tagliente, e Woody era diventato antipatico. La Pixar lo riscrisse in pochi mesi.'],
    ['Che accento aveva l’attore dentro il costume di Darth Vader?', 'Un accento campagnolo dell’Inghilterra sud-occidentale|Texano|Scozzese|Australiano', 'La troupe lo soprannominò «Darth Farmer». La voce di James Earl Jones fu doppiata dopo.'],
    ['Secondo l’azienda che la produce, che cos’è Hello Kitty?', 'Una bambina|Una gatta|Una coniglietta|Un’orsetta', 'Sanrio dice che è un’allegra bambina inglese di nome Kitty White, che vive vicino a Londra.'],
    ['Perché Mario ha i baffi?', 'Con così pochi pixel, una bocca era impossibile|Era ispirato a un vero idraulico|Un capo di Nintendo li aveva|Era uno scherzo', 'Il cappello evitava di disegnare i capelli, e la salopette faceva vedere bene le braccia.'],
    ['Che cosa non porta l’omino del Monopoly, anche se tanta gente è sicura del contrario?', 'Il monocolo|Il cilindro|Il papillon|I baffi', 'È un famoso «effetto Mandela». Non l’ha mai portato.'],
    ['Con che cosa fu fatta la prima rana Kermit?', 'Con un vecchio cappotto della madre di Jim Henson|Con un calzino verde|Con una pallina da tennis|Con uno strofinaccio', 'Con mezze palline da ping-pong al posto degli occhi, nel 1955.'],
    ['Quale vero nome rivelò un giorno di avere Cookie Monster?', 'Sid|Bob|Gus|Cookie', 'Lo rivelò nel 2004, aggiungendo che i biscotti gli piacciono e basta.'],
    ['Prima di scegliere un pupazzo, che cosa aveva preso in considerazione George Lucas per Yoda?', 'Una scimmia con una maschera|Un attore bambino|Un cartone animato|Un robot', 'Si parlò di una scimmia con un bastone. Vinse il pupazzo di Frank Oz.'],
    ['Ian Fleming, il creatore di James Bond, scrisse anche quale libro per bambini?', 'Chitty Chitty Bang Bang|Il Gruffalò|Matilde|Mary Poppins', 'Più tardi Roald Dahl scrisse le sceneggiature sia di quel film sia del Bond Si vive solo due volte.'],
    ['Nel 1926 Agatha Christie sparì. Per quanto tempo?', '11 giorni|11 ore|11 mesi|11 anni', 'La cercarono più di mille poliziotti. Ricomparve in un albergo termale, registrata con il cognome dell’amante del marito.'],
    ['Dove viveva Vincent van Gogh quando dipinse la Notte stellata?', 'In un manicomio|In un albergo di Parigi|Su una barca|Nella soffitta del fratello', 'La dipinse nel 1889 a Saint-Rémy, in parte a memoria della vista dalla sua finestra.'],
    ['Su che cosa si basa la famosa musica di Tetris?', 'Su un canto popolare russo su un venditore ambulante|Su una sonata di Mozart|Su un successo pop giapponese|Su una marcia militare', '«Korobeiniki» risale a una poesia del 1861. La versione del Game Boy l’ha resa un tormentone mondiale.'],
    ['Chi registrò quasi tutte le battute di Shrek prima di Mike Myers?', 'Chris Farley|Eddie Murphy|Jim Carrey|Robin Williams', 'Farley morì nel 1997 con gran parte del ruolo già fatto. Myers registrò tutto da capo, poi lo rifece ancora con l’accento scozzese.'],
    ['Perché il primo attore scelto per l’Uomo di latta del Mago di Oz fu sostituito?', 'Il trucco all’alluminio lo mandò in ospedale|Non sapeva cantare|Era troppo alto|Si rifiutava di ballare', 'Buddy Ebsen aveva respirato la polvere. Al suo sostituto diedero una pasta.'],
    ['Come finiva la prima versione di Pinocchio, nel 1881?', 'I cattivi impiccavano il burattino|Diventava un bambino vero|Si sposava|Volava sulla Luna', 'I lettori protestarono, e Carlo Collodi lo riportò in vita e continuò a scrivere.'],
  ],
  sports: [
    ['Quando Nadia Comăneci ottenne il primo 10 perfetto della ginnastica olimpica, che cosa mostrò il tabellone?', '1.00|10.00|0.00|ERROR', 'Aveva spazio solo per tre cifre, perché nessuno si aspettava un 10. Lei aveva 14 anni.'],
    ['Nel tennis inglese, che cosa vuol dire «love»?', 'Zero|Parità|Vantaggio|Un servizio vincente', 'Una teoria lo collega al francese «l’œuf», l’uovo, per la forma dello zero. Nessuno lo sa con certezza.'],
    ['Quale animale lavora a Wimbledon per tenere lontani i piccioni?', 'Un falco|Un gatto|Un gufo|Un cane', 'Un falco di Harris di nome Rufus fa questo lavoro da anni e ha perfino il suo pass.'],
    ['Le prime palline da golf, le «featheries», erano imbottite di che cosa?', 'Piume|Sabbia|Crine di cavallo|Cotone', 'Piume d’oca bollite venivano pressate in un involucro di cuoio bagnato, che asciugandosi si stringeva.'],
    ['Da quale paese veniva James Naismith, l’inventore della pallacanestro?', 'Dal Canada|Dagli Stati Uniti|Dalla Scozia|Dall’Inghilterra', 'Inventò il gioco in Massachusetts nel 1891, per tenere occupati gli studenti durante l’inverno.'],
    ['Chi ritrovò a Londra nel 1966 la Coppa del Mondo di calcio rubata?', 'Un cane di nome Pickles|Un tassista|Uno scolaro|Scotland Yard', 'La fiutò sotto una siepe, avvolta nella carta di giornale, una settimana dopo la sparizione.'],
    ['Che fine fece nel 1983 il trofeo originale dei Mondiali, la Coppa Rimet?', 'Fu rubata in Brasile e mai ritrovata|Fu fusa per farne medaglie|Andò persa in mare|Finì in un museo di Parigi', 'Il Brasile aveva potuto tenerla per sempre dopo aver vinto il terzo titolo nel 1970.'],
    ['Che cosa ispirò i cartellini giallo e rosso del calcio?', 'I semafori|Le carte da gioco|Un tramonto|Un segnale ferroviario', 'L’arbitro Ken Aston ebbe l’idea fermo a un incrocio di Londra. I cartellini arrivarono ai Mondiali del 1970.'],
    ['Nel cricket, quando un battitore viene eliminato senza punti, in inglese si dice che ha fatto che cosa?', 'Un duck, un’anatra|Un goose, un’oca|Un egg, un uovo|Un blank, un vuoto', 'Lo zero sul tabellone sembrava un uovo d’anatra.'],
    ['La media in battuta di Don Bradman nei Test è famosa perché è rimasta appena sotto quale cifra?', '100|50|200|1.000', 'Gli servivano solo quattro punti nell’ultimo turno, ma fu eliminato a zero e chiuse a 99,94.'],
    ['Perché i dischi da hockey su ghiaccio si congelano prima della partita?', 'Così scivolano meglio e rimbalzano meno|Così si vedono meno|Per renderli più pesanti|Per tenerli puliti', 'Durante la partita gli arbitri li cambiano man mano che si scaldano.'],
    ['Che tradizione hanno i vincitori della Stanley Cup?', 'Ogni giocatore passa un giorno con il trofeo|Si rasano la testa|Dormono sul ghiaccio|Ognuno se ne tiene un pezzo', 'È stata usata per battezzare neonati e per servire cereali, e viaggia sempre con un custode.'],
    ['Perché la maglia del leader del Tour de France è gialla?', 'Il giornale che creò la corsa era stampato su carta gialla|Il giallo è il colore nazionale francese|Così gli autisti vedono il leader|Era la tintura più economica', 'L’Auto lanciò la corsa nel 1903 per vendere più copie. La maglia gialla arrivò nel 1919. Per lo stesso motivo la maglia del Giro d’Italia è rosa come la Gazzetta.'],
    ['Quando si corse per la prima volta la staffetta della fiaccola olimpica?', 'Nel 1936|Nel 1896|Nel 1960|Nel 776 a.C.', 'Fu inventata per i Giochi di Berlino, portando la fiamma da Olimpia, in Grecia.'],
    ['Da dove viene il granito delle pietre da curling olimpiche?', 'Da una minuscola isola scozzese|Dalla Norvegia|Dalle Alpi svizzere|Dal Canada', 'Ailsa Craig è un santuario di uccelli, quindi la roccia si raccoglie solo ogni qualche anno. Un po’ viene anche dal Galles.'],
    ['Che cosa usavano come rete i primi giocatori vittoriani di ping-pong?', 'Una fila di libri|Una sciarpa|Una rete da pesca|Una racchetta da tennis', 'Le racchette potevano essere coperchi di scatole di sigari, e la pallina un tappo di champagne arrotondato.'],
    ['Quante piume ha un volano da badminton di alto livello?', '16|8|24|4', 'Sono piume d’oca, possibilmente tutte della stessa ala, così il volano gira in modo uniforme.'],
    ['Quale sport di racchetta ha il colpo più veloce mai misurato?', 'Il badminton|Il tennis|Lo squash|Il ping-pong', 'Nel 2023 una schiacciata è stata cronometrata a 565 km/h, anche se il volano rallenta prestissimo.'],
    ['La coppa dei Mondiali di rugby porta il nome di chi?', 'William Webb Ellis|Il principe William|William Wordsworth|William Shakespeare', 'La leggenda dice che nel 1823, alla Rugby School, prese in mano la palla durante una partita di calcio. Gli storici ne dubitano.'],
    ['Più o meno in quanto tempo una squadra di Formula 1 cambia tutte e quattro le gomme in un pit stop?', 'Meno di 2 secondi|Circa 10 secondi|Circa 30 secondi|Circa un minuto', 'Nel 2023 la McLaren ci ha messo 1,80 secondi, con circa 20 meccanici.'],
    ['Quale pezzo degli scacchi un tempo era il più debole della scacchiera?', 'La regina|L’alfiere|La torre|Il re', 'Poteva muoversi di una sola casella in diagonale fino al 1475 circa, quando i giocatori spagnoli la resero il pezzo più forte.'],
    ['«Scacco matto» viene da parole persiane che significano che cosa?', 'Il re è impotente|La partita è finita|Uccidi la regina|Ben giocato', '«Shah mat». Il gioco arrivò in Europa passando dalla Persia e dal mondo arabo.'],
    ['Quante posizioni possibili ha un cubo di Rubik?', 'Circa 43 miliardi di miliardi|Circa 43 milioni|Circa 4.300|Circa 43 miliardi', 'Eppure ognuna si può risolvere in 20 mosse o meno.'],
    ['Quanti anni avevano le medaglie d’oro e d’argento della prima gara olimpica femminile di skateboard street, nel 2021?', '13|17|21|25', 'La giapponese Momiji Nishiya vinse l’oro e la brasiliana Rayssa Leal l’argento.'],
    ['Dove si sono svolte le gare di surf delle Olimpiadi di Parigi 2024?', 'A Tahiti|A Biarritz|A Nizza|In Bretagna', 'A circa 15.700 km da Parigi, sulla famosa onda di Teahupo’o.'],
    ['Quanti anni aveva Pelé quando vinse il suo primo Mondiale?', '17|21|25|19', 'Segnò due gol nella finale del 1958 e lo vinse altre due volte, nel 1962 e nel 1970.'],
    ['Per quanto tempo la Federcalcio inglese vietò le partite femminili nei suoi campi?', '50 anni|5 anni|1 anno|100 anni', 'Dal 1921 al 1971. Le partite femminili attiravano folle di oltre 50.000 persone.'],
    ['Chi vinse nel 1973 la «Battaglia dei sessi» del tennis?', 'Billie Jean King|Bobby Riggs', 'Circa 90 milioni di persone la videro vincere in due set a zero.'],
    ['Quando compiono ufficialmente un anno in più tutti i purosangue da corsa dell’emisfero nord?', 'Il 1° gennaio|Il giorno del vero compleanno|Il giorno della prima corsa|Il giorno di mezza estate', 'Un puledro nato a dicembre ha ufficialmente un anno poche settimane dopo.'],
    ['Quanti punti segnò Wilt Chamberlain in una sola partita NBA nel 1962?', '100|50|81|72', 'Non c’erano telecamere. Una foto famosa lo mostra con in mano un foglio con scritto 100.'],
    ['Dove nacque il movimento paralimpico, nel 1948?', 'In un ospedale inglese|A Parigi|A Roma|Ad Atene', 'Il dottor Ludwig Guttmann organizzò dei giochi per i veterani feriti a Stoke Mandeville. Le prime Paralimpiadi arrivarono nel 1960, proprio a Roma.'],
    ['Perché un giro di golf ha 18 buche?', 'St Andrews ne aveva 18, e gli altri campi la copiarono|In una bottiglia di whisky ci sono 18 bicchierini|Lo decise un re|Ci vogliono circa 18 minuti a buca', 'Nel 1764 St Andrews ridusse il suo percorso da 22 buche a 18. La storia del whisky è un mito.'],
    ['Che cosa strofinano gli arbitri della Major League di baseball su ogni pallina nuova?', 'Un fango speciale preso da una riva segreta|Del gesso|Dell’olio d’oliva|Della saliva', 'Il fango, che viene da un posto nel New Jersey, toglie alla pallina la lucentezza scivolosa.'],
    ['La prima maratona olimpica, nel 1896, la vinse un greco che di mestiere trasportava che cosa?', 'Acqua|Posta|Pane|Legna', 'Spyridon Louis diventò un eroe nazionale. C’è chi dice che si fermò per un bicchiere di vino lungo il percorso.'],
    ['Nell’antico gioco della palla mesoamericano, con che cosa colpivano soprattutto la pesante palla di gomma i giocatori?', 'Con i fianchi|Con le mani|Con dei bastoni|Con la testa', 'Si giocò per oltre 3.000 anni, e alcune partite potrebbero essere finite con un sacrificio umano.'],
    ['Llanwrtyd Wells, in Galles, ospita un campionato del mondo di che cosa?', 'Snorkeling nella palude|Lotta con le dita dei piedi|Incantesimo dei lombrichi|Cerbottana con i piselli', 'Si nuota con pinne e boccaglio, senza poter usare le normali bracciate.'],
    ['Come si chiama oggi lo sport vero ispirato al Quidditch?', 'Quadball|Broomball|Snitchball|Hoopball', 'I giocatori corrono con un bastone tra le gambe. Ha cambiato nome nel 2022.'],
    ['Dove è stato inventato lo snooker?', 'In India|In Inghilterra|In Irlanda|In Australia', 'Lo inventarono degli ufficiali dell’esercito britannico a Jabalpur, intorno al 1875.'],
    ['Il badminton prende il nome da che cosa?', 'Dalla villa di campagna di un duca|Da un uccello|Dal suo inventore|Da una città indiana', 'Si giocava a Badminton House, in Inghilterra, negli anni Sessanta dell’Ottocento, ma le radici sono nel «poona» indiano.'],
    ['Nel kabaddi, che cosa deve continuare a fare un attaccante nella metà campo avversaria?', 'Ripetere «kabaddi»|Saltare su una gamba|Tenere una palla|Tenere gli occhi chiusi', 'Ripetere la parola senza sosta dimostra che l’attaccante non ha ripreso fiato.'],
    ['Il sepak takraw somiglia un po’ alla pallavolo, ma i giocatori non possono usare che cosa?', 'Le mani|I piedi|Una rete|Una palla', 'I giocatori fanno passare sopra la rete una palla intrecciata a calci e acrobazie, spesso a testa in giù.'],
    ['Più o meno quante ali di pollo mangiano gli americani nel fine settimana del Super Bowl?', 'Più di un miliardo|Circa un milione|Circa 10 milioni|Circa 100.000', 'Le stime del National Chicken Council sono arrivate a circa 1,45 miliardi.'],
    ['I golfisti gridano «Fore!» per avvisare la gente. Da dove viene, probabilmente?', 'Da «forecaddie», un aiutante mandato avanti|Dal numero quattro|Da un re scozzese|Dal francese «feu»', 'I forecaddie stavano più avanti nel percorso per vedere dove cadevano le palline.'],
    ['Nel 2000, quanto tempo dopo il calcio d’inizio fu espulso il calciatore inglese Lee Todd?', 'Circa 2 secondi|Circa 2 minuti|Circa 20 minuti|Prima che cominciasse la partita', 'Aveva imprecato per quanto era forte il fischietto dell’arbitro.'],
    ['Che cosa disse Usain Bolt di aver mangiato quasi sempre alle Olimpiadi di Pechino 2008?', 'Crocchette di pollo|Pasta|Sushi|Riso e fagioli', 'Secondo i suoi conti, circa 1.000 in dieci giorni, perché non si fidava del resto. Vinse tre ori.'],
    ['Nel 2002, in Madagascar, una partita di calcio finì 149–0. Come?', 'La squadra perdente segnò autogol per protesta|Il portiere si addormentò|Era un errore di battitura|L’altra squadra non si presentò', 'Lo Stade Olympique de l’Emyrne era arrabbiato per una decisione arbitrale in una partita precedente.'],
    ['Quanto ci mise ufficialmente il maratoneta giapponese Shizo Kanakuri a finire la maratona olimpica del 1912?', 'Più di 54 anni|Circa 3 ore|Circa 5 giorni|Non la finì mai', 'Si ritirò e tornò a casa senza dirlo a nessuno. Nel 1967 la Svezia lo invitò a tagliare il traguardo.'],
    ['Alle antiche Olimpiadi, chi vinceva il premio nella corsa dei carri?', 'Il proprietario dei cavalli|L’auriga|Il cavallo più veloce|Il favorito del pubblico', 'Così una principessa spartana, Cinisca, diventò la prima campionessa olimpica, anche se le donne non potevano nemmeno assistere.'],
    ['Quanto peso può perdere in sudore un pilota di Formula 1 durante una gara al caldo?', 'Fino a circa 3 kg|Circa 100 g|Circa 10 kg|Niente', 'Gli abitacoli possono diventare caldissimi, e i piloti indossano strati ignifughi dalla testa ai piedi.'],
    ['Secondo il regolamento ufficiale, qual è la partita a scacchi più lunga possibile?', 'Circa 6.000 mosse|Circa 200 mosse|Circa 600 mosse|Non c’è limite', 'Le regole sulla patta impediscono che vada avanti per sempre. La partita di torneo più lunga, nel 1989, è durata 269 mosse e più di 20 ore.'],
    ['Dove sono nati gli Harlem Globetrotters?', 'A Chicago|Ad Harlem|A Los Angeles|A Londra', 'Cominciarono nel 1926 e giocarono la prima partita ad Harlem solo nel 1968.'],
    ['Dove si disputarono le gare di nuoto delle Olimpiadi di Parigi 1900?', 'Nella Senna|In piscina|In mare|In un lago', 'Nuotare con la corrente rese i tempi stranamente veloci. In una gara a ostacoli bisognava passare sopra e sotto delle barche.'],
    ['Quanti anni aveva il medagliato olimpico più anziano di sempre?', '72|52|62|82', 'Il tiratore svedese Oscar Swahn vinse l’argento nel 1920.'],
    ['Con che punteggio finì la prima partita di pallacanestro, nel 1891?', '1–0|100–98|20–18|0–0', 'Con i cesti per le pesche e nove giocatori per parte, entrò un solo tiro.'],
    ['L’arciere sudcoreano Im Dong-hyun stabilì un record mondiale nel 2012 nonostante che cosa?', 'Fosse legalmente cieco|Tirasse con una mano sola|Avesse un braccio rotto|Non si fosse mai allenato', 'Vede il bersaglio come macchie di colore sfocate e mira usando quelle.'],
    ['In teoria, una Formula 1 ad alta velocità potrebbe fare che cosa?', 'Correre a testa in giù sul soffitto di una galleria|Volare|Galleggiare sull’acqua|Salire su un muro per sempre', 'Le ali la schiacciano verso il basso con una forza maggiore del suo stesso peso. Nessuno ci ha mai provato.'],
    ['Nell’antica Olimpia, gli atleti sorpresi a imbrogliare dovevano pagare che cosa?', 'Statue di bronzo di Zeus all’ingresso dello stadio|Un banchetto per tutti|Un tempio nuovo|Corone d’oro per i rivali', 'Ogni statua riportava il nome dell’imbroglione, che restava svergognato per secoli. I basamenti di pietra fiancheggiano ancora il sentiero.'],
  ],
  words: [
    ['«Utopia» viene da parole greche che significano che cosa?', 'Nessun luogo|Terra perfetta|Isola soleggiata|Popolo felice', 'La coniò Tommaso Moro nel 1516, giocando con «eutopia», luogo felice.'],
    ['Che cosa significa letteralmente «disastro»?', 'Cattiva stella|Grande caduta|Nave rotta|Fortuna perduta', 'Un tempo la sfortuna si dava alla posizione degli astri. Ecco perché si nasce «sotto una cattiva stella».'],
    ['Da dove viene la parola «alfabeto»?', 'Dalle prime due lettere greche|Da un re fenicio|Dal latino per «tutte le lettere»|Da un dio romano', 'Alfa e beta, che a loro volta derivavano da lettere fenicie più antiche.'],
    ['Nell’inglese «nightmare», «incubo», che cos’era la «mare»?', 'Uno spirito maligno che si sedeva sui dormienti|Una cavalla|Il mare|Una nuvola scura', 'Nel folclore antico, la «mare» premeva sul petto di chi dormiva. Anche il nostro «incubo» viene dal latino incubus, «chi giace sopra».'],
    ['«Azzardo» viene da una parola antica che indicava che cosa?', 'Un gioco di dadi|Un animale selvatico|Un ponte crollato|Un incendio', 'Probabilmente dall’arabo az-zahr, il dado. I giocatori sapevano bene che cos’era il rischio.'],
    ['L’inglese «window», «finestra», viene da parole del norreno antico che significano che cosa?', 'Occhio del vento|Buco della casa|Porta di vetro|Fessura di luce', 'Le prime finestre erano buchi aperti, da cui entrava il vento oltre alla luce.'],
    ['Che cosa voleva dire all’inizio l’inglese «husband», «marito»?', 'Padrone di casa|Uomo forte|Portatore dell’anello|Figlio del contadino', 'Viene dal norreno per «chi abita la casa». L’agricoltura in inglese si chiama ancora «husbandry».'],
    ['L’inglese «lord», «signore», viene da una parola dell’inglese antico che significa che cosa?', 'Guardiano della pagnotta|Proprietario terriero|Uomo alto|Portatore di spada', 'E «lady» voleva dire «colei che impasta il pane». Il pane contava, eccome.'],
    ['Che cosa voleva dire all’inizio «shampoo» in inglese?', 'Un massaggio|Un sapone|Una tinta per capelli|Un bagno', 'Viene da una parola hindi che significa premere o impastare.'],
    ['Quale lingua ha dato all’inglese, e anche a noi, la parola «pigiama»?', 'Il persiano, attraverso hindi e urdu|Il francese|Lo spagnolo|Il turco', 'Vuol dire «indumento per le gambe».'],
    ['Che cosa significa in origine «bungalow»?', 'Alla maniera del Bengala|Casa bassa|Capanno da giardino|Casa per le vacanze', 'I britannici in India chiamarono queste case a un piano con il nome del Bengala.'],
    ['Da quale lingua viene «tycoon», il magnate?', 'Dal giapponese|Dal cinese|Dall’hindi|Dal turco', 'Da taikun, «grande signore», un titolo che gli stranieri usavano per lo shogun.'],
    ['La parola «boss», che usiamo anche noi, viene da quale lingua?', 'Dall’olandese|Dal tedesco|Dal francese|Dal latino', 'Da baas, «padrone», come dicevano i coloni olandesi a New York.'],
    ['«Sabotaggio» viene da «sabot», parola francese per che cosa?', 'Uno zoccolo di legno|Un martello|Una chiave inglese|Un soldato', '«Saboter» voleva dire sbatacchiare in giro, o fare un lavoro in modo goffo.'],
    ['Chi era il Jumbo originale?', 'Un enorme elefante dello zoo di Londra|Un aereo|Un gamberetto|Una nave', 'Quando P. T. Barnum lo comprò nel 1882, il pubblico britannico si indignò.'],
    ['Da dove viene la parola «boicottare»?', 'Da un amministratore di terre irlandese che tutti evitavano|Da una parola olandese per «non comprare»|Da una nave|Da un gioco', 'Nel 1880 i vicini del capitano Charles Boycott si rifiutarono di lavorare, commerciare e perfino parlare con lui.'],
    ['Da dove viene la parola «silhouette»?', 'Da un tirchio ministro delle finanze francese|Da uno spettacolo di ombre cinesi|Da una ballerina|Dal pennello di un pittore', 'Il nome di Étienne de Silhouette finì per indicare qualsiasi cosa fatta al risparmio, come un rapido ritratto di profilo.'],
    ['Il «leotard», il body da ginnastica degli inglesi, prende il nome da chi?', 'Da un trapezista francese|Da un ballerino|Da un imperatore romano|Da un sarto', 'Jules Léotard, che ne indossava uno negli anni Cinquanta dell’Ottocento. Era «il giovane audace sul trapezio volante» della canzone.'],
    ['La ghigliottina prende il nome da chi?', 'Da un medico che voleva esecuzioni meno crudeli|Dal suo inventore|Da un re|Da un boia', 'Joseph-Ignace Guillotin non la inventò, ed era contrario alla pena di morte.'],
    ['Il cardigan prende il nome da che cosa?', 'Da un conte che guidò la carica della Brigata leggera|Da una pecora gallese|Da una città scozzese|Da un punto a maglia', 'Le sue truppe indossavano giacche lavorate a maglia nella guerra di Crimea.'],
    ['Le basette, in inglese «sideburns», prendono il nome da chi?', 'Da un generale della guerra civile americana|Da un barbiere|Da una ferrovia|Da un clan scozzese', 'Le enormi basette di Ambrose Burnside erano famose. Il suo nome fu girato al contrario.'],
    ['Da chi viene il verbo inglese «mesmerize», ipnotizzare?', 'Da un medico che curava col «magnetismo animale»|Da un prestigiatore|Da un incantatore di serpenti|Da un pittore', 'Franz Mesmer attirava folle nella Parigi degli anni Ottanta del Settecento, finché una commissione reale stabilì che non c’era niente di vero.'],
    ['La parola «panico» viene da quale dio?', 'Pan|Zeus|Marte|Thor', 'Si diceva che il dio greco della natura selvaggia riempisse i viandanti di una paura improvvisa.'],
    ['Un «atlante» di carte geografiche prende il nome da chi?', 'Da un titano che reggeva il cielo|Da un marinaio|Da un cartografo romano|Da un re di Atlantide', 'Il cartografo Gerardo Mercatore diede questo nome alla sua raccolta nel 1595.'],
    ['«Settembre» viene dal latino per quale numero?', 'Sette|Nove|Sei|Dieci', 'L’anno romano più antico cominciava a marzo, quindi settembre era il settimo mese.'],
    ['Che cosa significa letteralmente «compagno»?', 'Uno con cui dividi il pane|Uno con cui cammini|Un commilitone|Un vicino', 'Dal latino cum, «con», e panis, «pane». Lo stesso vale per l’inglese «companion».'],
    ['Che cosa significa «emoji» in giapponese?', 'Carattere-immagine|Icona di emozione|Faccina sorridente|Piccolo sentimento', 'E vuol dire immagine e moji carattere. La somiglianza con «emozione» è una coincidenza.'],
    ['Perché le email indesiderate si chiamano «spam»?', 'Per uno sketch dei Monty Python|È la sigla inglese di «posta stupida e inutile»|Per un virus informatico|Per il nome di un programmatore', 'Nello sketch del 1970 dei vichinghi cantano «Spam» di continuo finché nessuno riesce più a parlare.'],
    ['Che cosa significa «wiki» in hawaiano?', 'Veloce|Sapere|Tutti|Scrivere', 'Il primo wiki prese il nome da una navetta veloce dell’aeroporto di Honolulu.'],
    ['La parola inglese «yahoo», per una persona rozza e maleducata, viene da quale libro?', 'I viaggi di Gulliver|Robinson Crusoe|L’isola del tesoro|Moby Dick', 'Gli Yahoo di Jonathan Swift erano creature bestiali governate da cavalli saggi.'],
    ['«Serendipità» viene da un antico nome di quale paese?', 'Sri Lanka|India|Persia|Egitto', 'La coniò Horace Walpole nel 1754, da una fiaba intitolata «I tre principi di Serendippo».'],
    ['In quale libro comparve per la prima volta la parola «nerd»?', 'In un libro del Dr. Seuss|In un libro di Harry Potter|In un manuale di scienze|In un’opera di Shakespeare', '«If I Ran the Zoo», nel 1950. Lì un nerd era solo una creatura buffa.'],
    ['Quale autore inventò la parola inglese «chortle», ridacchiare?', 'Lewis Carroll|William Shakespeare|Charles Dickens|Roald Dahl', 'Fonde «chuckle» (ridacchiare) e «snort» (sbuffare), in Attraverso lo specchio (1871).'],
    ['Quale poeta inventò la parola «pandemonio»?', 'John Milton|William Shakespeare|Lord Byron|Omero', 'Nel Paradiso perduto (1667), Pandæmonium è la capitale dell’Inferno.'],
    ['Prima degli anni Trenta dell’Ottocento, come si chiamavano di solito gli scienziati in inglese?', 'Filosofi naturali|Alchimisti|Maghi|Ingegneri', 'William Whewell propose «scientist» nel 1834. All’inizio a molti non piaceva.'],
    ['Quale di questi è un anagramma dell’inglese «dormitory», «dormitorio»?', 'Dirty room («stanza sporca»)|Dim story|Rotted rim|Dry motor', 'E «astronomer», astronomo, si riordina in «moon starer», «chi fissa la luna».'],
    ['Quale lingua ha il record di lettere nel suo alfabeto?', 'Il khmer|Il russo|L’hawaiano|Il greco', 'La lingua della Cambogia ha 74 lettere, secondo il Guinness dei primati.'],
    ['A La Gomera, nelle Canarie, alcune persone parlano spagnolo in che modo?', 'Fischiando|Schioccando la lingua|Canticchiando|Con i tamburi', 'Il silbo gomero si sente per chilometri attraverso le valli e si insegna a scuola.'],
    ['Quale lingua usa gli schiocchi come consonanti?', 'Lo xhosa|Lo swahili|L’amarico|Lo yoruba', 'Era la prima lingua di Nelson Mandela. La X di Xhosa è essa stessa uno schiocco.'],
    ['Quale lettera ha mantenuto quasi la stessa forma per circa 3.000 anni?', 'O|A|X|Z', 'In fenicio era una lettera chiamata ayin, che voleva dire occhio.'],
    ['Quale lettera viene spesso chiamata la più giovane dell’alfabeto inglese?', 'J|Z|W|Q', 'Nacque da una i decorata e fu considerata una lettera a sé solo dal Seicento. Nell’alfabeto italiano di 21 lettere, poi, non c’è nemmeno.'],
    ['Il simbolo & è nato come un modo schiacciato di scrivere che cosa?', '«et», «e» in latino|«and»|«plus»|«add»', 'I bambini inglesi che recitavano l’alfabeto finivano con «and per se and», che diventò «ampersand».'],
    ['Dire per sbaglio «You have hissed all my mystery lectures» invece di «missed all my history lectures» si chiama come?', 'Spoonerismo|Malapropismo|Gioco di parole|Refuso', 'Da William Spooner, un professore di Oxford famoso per scambiare i suoni, anche se molte delle sue gaffe le inventarono gli studenti.'],
    ['Quale breve verbo inglese ha più significati nell’Oxford English Dictionary?', 'Run|Set|Go|Take', 'Nel 2011 ne aveva 645, e superò «set».'],
    ['Che cosa c’entra la parola inglese «quiz» con una famosa leggenda?', 'Un dublinese scommise di poter inventare una parola|È latino per «chi è?»|L’ha inventata un presentatore di quiz|Vuol dire esame in greco', 'La storia dice che fece scrivere «QUIZ» col gesso sui muri durante la notte. È quasi certamente inventata.'],
    ['Quale di queste parole inglesi usa 15 lettere senza ripeterne nessuna?', 'Uncopyrightable|Unpredictability|Misunderstanding|Characteristics', 'Lo stesso vale per «dermatoglyphics», lo studio delle impronte digitali.'],
    ['Quale di queste parole inglesi ha le lettere in ordine alfabetico?', 'Almost|Little|Garden|Sister', 'A, l, m, o, s, t. Lo stesso vale per «biopsy», «chintz» e «begins».'],
    ['Che cos’è un «contronimo», come l’inglese «sanction» o il nostro «spolverare»?', 'Una parola che è il contrario di se stessa|Una parola senza vocali|Una parolaccia|Una parola cortissima', 'Spolverare i mobili toglie la polvere; spolverare una torta di zucchero a velo la aggiunge. In inglese «to dust» fa lo stesso.'],
    ['Nello slang britannico, che cosa vuol dire «Bob’s your uncle»?', '«Ed è fatta»|«Sei nei guai»|«Ciao»|«Arrivederci»', 'Una teoria lo collega a un primo ministro che nel 1887 diede un lavoro al nipote.'],
    ['Come si chiama il contrario del déjà vu, quando una cosa familiare all’improvviso sembra strana?', 'Jamais vu|Bon voyage|Faux pas|Je ne sais quoi', 'Ripeti una parola tante volte e comincerà a sembrare senza senso.'],
    ['Quale lingua d’Europa non è imparentata con nessun’altra lingua viva?', 'Il basco|L’ungherese|Il finlandese|L’albanese', 'Si parlava sui Pirenei prima che arrivassero le lingue indoeuropee.'],
    ['Da dove viene «Mayday», la chiamata di soccorso?', 'Dal francese «m’aidez», aiutatemi|Dal mese di maggio|Da un marinaio di nome May|Da un codice radio', 'La scelse nel 1923 Fred Mockford, operatore radio di un aeroporto di Londra.'],
    ['Che cosa vuol dire «SOS»?', 'Niente: è solo facile da battere in Morse|Save our souls, salvate le nostre anime|Save our ship, salvate la nostra nave|Send our signal', 'Tre punti, tre linee, tre punti. Le frasi sono arrivate dopo.'],
    ['Quale alfabeto fu pensato, dicevano i suoi creatori, perché una persona saggia potesse impararlo in una mattina?', 'L’hangul coreano|I kana giapponesi|Il greco|Il cirillico', 'Il re Sejong lo introdusse nel 1446 perché anche la gente comune potesse leggere.'],
    ['Chi coniò la parola «googol», per un 1 seguito da 100 zeri?', 'Un bambino di nove anni|Il cane di un matematico|Un computer|Un filosofo greco', 'Milton Sirotta la inventò nel 1920 per suo zio, il matematico Edward Kasner.'],
    ['La parola inglese «bedlam», che vuol dire caos, viene da che cosa?', 'Da un ospedale psichiatrico di Londra|Da un uccello rumoroso|Da un negozio di letti|Da una battaglia', 'Il Bethlem Hospital un tempo faceva pagare i visitatori che venivano a guardare i pazienti.'],
    ['«Whisky» viene da parole gaeliche che significano che cosa?', 'Acqua della vita|Acqua che brucia|Bevanda d’oro|Succo d’orzo', 'Uisge beatha: proprio come la nostra acquavite. E «vodka», invece, vuol dire «acquetta».'],
    ['Che cosa voleva dire in origine il «tril» dell’inglese «nostril», «narice»?', 'Buco|Pelo|Fiato|Ala', 'L’inglese antico nosþyrl era semplicemente «buco del naso». La stessa radice ha dato «thrill», che un tempo voleva dire trafiggere.'],
    ['Perché un dizionario inserì la parola inventata «esquivalience»?', 'Per scoprire chi lo copiava|Per sbaglio|Come scherzo per il redattore|Un tempo era una parola vera', 'Voleva dire «sottrarsi ai propri doveri». Quando comparve su un sito concorrente, la copiatura fu smascherata.'],
    ['«Buffalo buffalo Buffalo buffalo buffalo buffalo Buffalo buffalo» che cos’è?', 'Una frase inglese grammaticalmente corretta|Uno scioglilingua senza senso|Un coro da stadio|Un refuso', 'Vuol dire: i bisonti di Buffalo, New York, che altri bisonti di Buffalo maltrattano, maltrattano a loro volta bisonti di Buffalo.'],
    ['Perché l’inglese «colonel», colonnello, si pronuncia come «kernel»?', 'Il suono viene dal francese, la grafia dall’italiano|È un refuso|Lo decise un re|Viene dal mais', 'Il francese «coronel» diede il suono. Il nostro «colonnello» più tardi fissò la grafia.'],
    ['Nelle firme che ci restano, come non scrisse mai il suo nome Shakespeare?', 'Shakespeare|Shakspere|Shaksper|Shakspeare', 'Restano sei firme, scritte in modi diversi, e nessuna come lo scriviamo oggi.'],
  ],
  money: [
    ['La parola inglese «money», come la nostra «moneta», viene dal tempio di quale dea romana?', 'Giunone|Venere|Minerva|Diana', 'Roma coniava le sue monete nel tempio di Giunone Moneta.'],
    ['Alcune delle prime monete del mondo furono coniate in Lidia intorno al 600 a.C. Dov’era?', 'Nell’attuale Turchia|Nell’attuale Grecia|Nell’attuale Egitto|Nell’attuale Italia', 'Erano fatte di elettro, una lega naturale di oro e argento.'],
    ['Quale di queste cose fu usata come denaro per secoli in Africa e in Asia?', 'Le conchiglie di ciprea|Le pigne|Le piume|Le ghiande', 'Erano difficili da falsificare e duravano anni.'],
    ['Sull’isola di Yap, nel Pacifico, che cosa sono i giganteschi «rai» usati come denaro?', 'Dischi di pietra|Conchiglie|Denti di balena|Maiali', 'Alcuni sono più alti di una persona. Non si spostano quasi mai: tutti si ricordano semplicemente chi possiede quale.'],
    ['Quale paese emise le prime banconote d’Europa, nel 1661?', 'Svezia|Italia|Inghilterra|Paesi Bassi', 'Le stampò la Stockholms Banco, che pochi anni dopo fallì.'],
    ['Da dove viene, con ogni probabilità, il simbolo $?', 'Dal peso spagnolo, scritto «ps»|Dalle lettere U e S|Da un serpente su una moneta|Dall’albero di una nave', 'I dollari d’argento spagnoli si usavano in tutta l’America delle origini.'],
    ['La parola «dollaro» viene dal «tallero», una moneta coniata per la prima volta dove?', 'In una valle di miniere d’argento, oggi in Cechia|Ad Amsterdam|In Spagna|In Scozia', 'Le monete di Joachimsthal si chiamavano joachimsthaler, poi thaler.'],
    ['Da quale parola viene il simbolo £?', 'Libra, la libbra latina|London|Ledger, il libro mastro|Lord', 'Una libbra d’argento un tempo si tagliava in 240 penny. Lo stesso simbolo si usava per la nostra lira, che viene sempre da libra.'],
    ['Nel 1946 l’Ungheria emise una banconota da quanti pengő?', '100 miliardi di miliardi|1 milione|1 miliardo|100.000 miliardi', 'I prezzi raddoppiavano circa ogni 15 ore: la peggiore inflazione mai registrata.'],
    ['La banconota più grande dello Zimbabwe, emessa nel 2009, aveva un valore nominale di quanto?', '100.000 miliardi di dollari|1 milione di dollari|1 miliardo di dollari|1.000 dollari', 'Oggi i collezionisti la pagano molto più di quanto sia mai valsa nei negozi.'],
    ['Durante l’iperinflazione tedesca del 1923, che cosa facevano alcuni con le banconote?', 'Le bruciavano per scaldarsi|Le mangiavano|Le incorniciavano|Le scambiavano con medaglie', 'La carta moneta costava meno della legna. I prezzi raddoppiavano ogni pochi giorni.'],
    ['Perché quasi tutti i PIN bancari hanno quattro cifre?', 'La moglie dell’inventore ne ricordava solo quattro|Ne entravano quattro sulle prime tastiere|Lo diceva la legge|Il quattro porta fortuna', 'John Shepherd-Barron aveva previsto sei cifre per il suo sportello automatico.'],
    ['Chi fu la prima donna ritratta su una banconota americana?', 'Martha Washington|Eleanor Roosevelt|Susan B. Anthony|Harriet Tubman', 'Comparve su un certificato d’argento da 1 dollaro nel 1886.'],
    ['Che cosa hanno di speciale i ponti sulle banconote in euro?', 'Sono immaginari|Sono tutti a Bruxelles|Sono tutti a Parigi|Li hanno disegnati dei bambini', 'Mostrano stili architettonici europei, per non favorire nessun paese. Più tardi una città olandese li ha costruiti davvero.'],
    ['Perché Wall Street, a New York, si chiama così?', 'I coloni olandesi ci costruirono un muro|Ci viveva un banchiere di nome Wall|Corre lungo le mura di un forte|Un tempo era una parete di negozi', 'Negli anni Cinquanta del Seicento i coloni di Nuova Amsterdam ci alzarono un muro di legno per difendersi.'],
    ['Un’azienda giapponese fondata nel 578 è una delle più antiche del mondo. Che cosa costruisce?', 'Templi|Spade|Barche|Ponti', 'La Kongō Gumi è stata guidata dalla stessa famiglia per più di 1.400 anni.'],
    ['Che cosa mostrava il primo logo di Apple?', 'Isaac Newton sotto un albero|Una mela arcobaleno|Un computer|Una pera morsicata', 'Nel 1977 fu sostituito dalla mela arcobaleno con il morso.'],
    ['Il Cervino sulla confezione del Toblerone nascondeva quale animale?', 'Un orso|Una capra|Un’aquila|Una mucca', 'Berna, dove fu prodotto per la prima volta, ha un orso nello stemma. Il Cervino è sparito nel 2023, quando parte della produzione si è spostata in Slovacchia.'],
    ['Una teoria dice che i salvadanai a forma di maialino vengono da «pygg». Che cos’era?', 'Un tipo di argilla|Una moneta|Un banchiere|Un contadino', 'Vasi di argilla arancione chiamata pygg contenevano monete, e forse i vasai li facevano a forma di maiale per scherzo.'],
    ['Perché nel 2025 gli Stati Uniti hanno smesso di coniare nuovi penny?', 'Ognuno costava più di un centesimo da produrre|Nessuno li usava|Era finito il rame|L’ha ordinato un tribunale', 'Un penny costava quasi 4 centesimi da produrre. Quelli vecchi hanno ancora corso legale.'],
    ['Il ritratto di chi è comparso sul denaro del maggior numero di paesi?', 'La regina Elisabetta II|George Washington|Napoleone|Simón Bolívar', 'Il Guinness dei primati ha contato almeno 35 paesi.'],
    ['Da dove viene la parola inglese «bank»?', 'Dall’italiano «banca», cioè il banco|Dal tedesco «bang», schianto|Da un banchiere romano|Dalla riva di un fiume', 'I cambiavalute lavoravano al banco. Un banco rotto, la «banca rotta», ha dato all’inglese «bankrupt».'],
    ['«Budget» viene da una vecchia parola francese per che cosa?', 'Una borsetta di cuoio|Un conto|Una scatola di monete|Una lista', 'La bougette era un piccolo borsellino. Il ministro delle finanze britannico porta ancora una valigetta rossa.'],
    ['Lloyd’s di Londra, il famoso mercato delle assicurazioni, nacque in che cosa?', 'In un caffè|In una chiesa|Su una nave|In un pub', 'Negli anni Ottanta del Seicento armatori e assicuratori si incontravano al caffè di Edward Lloyd.'],
    ['Che cosa confronta il «Big Mac Index»?', 'I prezzi nei vari paesi|Le dimensioni degli hamburger|Gli stipendi nei fast food|Le calorie', 'L’Economist lo inventò nel 1986, come modo scherzoso per vedere se le monete sono sopravvalutate o sottovalutate.'],
    ['Le banconote di quale paese riportano il loro valore in 17 lingue?', 'India|Svizzera|Canada|Belgio', 'Hindi e inglese sul davanti, più altre 15 lingue in un riquadro sul retro.'],
    ['Le banconote di quale paese sono stampate in verticale?', 'Svizzera|Giappone|Norvegia|Brasile', 'Le banconote attuali in franchi svizzeri sono pensate per essere tenute dritte.'],
    ['Lo yen giapponese e lo yuan cinese hanno un nome che significa che cosa?', 'Rotondo|Oro|Moneta|Re', 'Come il won coreano, i nomi vengono dalle monete d’argento rotonde un tempo usate in tutta l’Asia orientale.'],
    ['Che cosa ha di insolito la moneta da un dollaro canadese?', 'Ha una strolaga («loon»), quindi si chiama «loonie»|È quadrata|Ha un buco al centro|È di legno', 'La moneta da 2 dollari arrivata dopo si chiama «toonie».'],
    ['Che cosa faceva il fondatore della Ferrari prima di costruire le sue auto?', 'Correva per l’Alfa Romeo|Faceva trattori|Era un pilota d’aereo|Faceva biciclette', 'Enzo Ferrari fondò la Scuderia Ferrari nel 1929 come squadra corse dell’Alfa Romeo.'],
    ['Quanto vendette la Coca-Cola nel suo primo anno, il 1886?', 'Circa nove bicchieri al giorno|Circa 9.000 bottiglie al giorno|Circa un milione di bicchieri|Niente', 'Incassò meno di quanto era costato avviarla.'],
    ['Qual era il premio originale dei primi Nobel, nel 1901?', 'Circa 20 anni di stipendio di un professore universitario|Un orologio d’oro|Una casa a Stoccolma|Solo una medaglia', 'Alfred Nobel lasciò quasi tutto il suo patrimonio, fatto con la dinamite, per finanziare i premi.'],
    ['Quale viene spesso considerato il primo acquisto online sicuro, nel 1994?', 'Un CD di Sting|Una pizza|Un libro|Un biglietto aereo', 'Uno studente di Filadelfia pagò 12,48 dollari più la spedizione per «Ten Summoner’s Tales», con i dati della carta crittografati.'],
    ['Quando comparve per la prima volta un sovrano britannico sulle banconote della Banca d’Inghilterra?', 'Nel 1960|Nel 1694|Nel 1837|Nel 1901', 'La regina Elisabetta II. Per quasi 270 anni prima di allora, le banconote mostravano Britannia.'],
    ['Procter & Gamble nacque nel 1837 producendo che cosa?', 'Candele e sapone|Dentifricio|Pannolini|Rasoi', 'William Procter faceva candele e James Gamble sapone. Le loro mogli erano sorelle.'],
    ['Sears, un tempo il più grande negozio d’America, cominciò vendendo per posta che cosa?', 'Orologi|Semi|Libri|Biciclette', 'Nel 1886 Richard Sears, capostazione ferroviario, vendette una cassa di orologi che un gioielliere non voleva.'],
    ['Che fine fanno le monete lanciate nella Fontana di Trevi, a Roma?', 'Vanno a un’associazione di beneficenza che aiuta i poveri|Vanno nel bilancio del Comune|Restano lì per sempre|Le tiene il Papa', 'Ogni anno si raccoglie più di un milione di euro, che va alla Caritas.'],
    ['In Scozia, chi stampa le banconote?', 'Tre normali banche commerciali|Solo la Banca d’Inghilterra|Il re in persona|Nessuno: la Scozia usa solo monete', 'Bank of Scotland, Royal Bank of Scotland e Clydesdale Bank emettono ciascuna i propri modelli.'],
    ['William Wrigley Jr. all’inizio regalava la gomma da masticare insieme a che cosa?', 'Al lievito in polvere|Al sapone|Ai giornali|Ai sigari', 'La gomma piacque più del lievito, così cambiò prodotto.'],
    ['Nel 1989 la Pepsi possedette per breve tempo che cosa, grazie a un accordo con l’Unione Sovietica?', 'Vecchi sottomarini e navi da guerra|Una stazione spaziale|Uno stadio di Mosca|Una centrale nucleare', 'Ricevette 17 sottomarini, un incrociatore, una fregata e un cacciatorpediniere in cambio di cola, e li vendette come rottami.'],
    ['Nel 1996 una pubblicità della Pepsi scherzava che con 7 milioni di punti si vinceva che cosa?', 'Un caccia militare|Uno yacht|Un’isola|Un razzo', 'Uno studente raccolse circa 700.000 dollari per riscuoterlo. Il tribunale stabilì che la pubblicità era ovviamente uno scherzo.'],
    ['Come nacque l’idea dei mobili da montare dell’IKEA?', 'Un dipendente smontò un tavolo per farlo stare in auto|Un incendio in fabbrica|Una legge svedese|La vendita per posta', 'Gillis Lundgren lo fece nel 1956, e l’azienda capì quanto avrebbe risparmiato sulle spedizioni.'],
    ['Nel 2024 un’opera d’arte fatta di una banana attaccata al muro con il nastro adesivo fu venduta per circa quanto?', '6,2 milioni di dollari|62 dollari|6.200 dollari|62.000 dollari', 'L’opera, «Comedian», è di Maurizio Cattelan. Il compratore, un imprenditore delle criptovalute, poi si è mangiato la banana.'],
    ['Nel 1925 il truffatore Victor Lustig riuscì a «vendere» che cosa?', 'La Torre Eiffel, come rottame|Il Big Ben|La Luna|Il Colosseo', 'Il compratore si vergognava troppo per andare alla polizia, così Lustig ci riprovò.'],
    ['Come era soprannominata la prima carta moneta cinese?', 'Denaro volante|Denaro dei fantasmi|Carta del drago|Monete di nuvola', 'Era così leggera che il vento poteva portarla via, a differenza delle pesanti file di monete.'],
  ],
  myths: [
    ['Le diverse parti della lingua sentono sapori diversi.', 'Mito|Realtà', 'La «mappa della lingua» nacque da un articolo tedesco del 1901 tradotto male. Ogni parte sente ogni sapore.'],
    ['Nel Medioevo le persone istruite credevano che la Terra fosse piatta.', 'Mito|Realtà', 'Gli studiosi sapevano che era rotonda. Gli antichi greci ne avevano perfino stimato le dimensioni.'],
    ['Una mamma uccello abbandona il pulcino se lo ha toccato un essere umano.', 'Mito|Realtà', 'Quasi tutti gli uccelli hanno un olfatto debole e continuano a prendersi cura dei piccoli.'],
    ['I lemming si gettano dalle scogliere in suicidi di massa.', 'Mito|Realtà', 'Un documentario Disney del 1958 inscenò la scena spingendo i lemming giù da una sporgenza.'],
    ['Toccando un rospo ti vengono le verruche.', 'Mito|Realtà', 'Le verruche vengono da un virus umano. I bozzi del rospo sono solo ghiandole.'],
    ['Gli istrici possono sparare gli aculei contro i nemici.', 'Mito|Realtà', 'Gli aculei si staccano facilmente, ma l’istrice deve toccarti.'],
    ['I «ragni» dalle zampe lunghissime sono mortali, ma hanno le zanne troppo corte per morderci.', 'Mito|Realtà', 'Gli animali chiamati così sono innocui, e alcuni non hanno proprio veleno.'],
    ['Un anno di un cane equivale a sette anni umani.', 'Mito|Realtà', 'All’inizio i cani invecchiano in fretta: un cane di un anno è più simile a un adolescente. Le razze grandi poi invecchiano più rapidamente.'],
    ['I gatti atterrano sempre sulle zampe.', 'Mito|Realtà', 'Hanno un forte riflesso di rotazione, ma possono comunque atterrare male e farsi male.'],
    ['Il tacchino fa venire sonno per via del triptofano che contiene.', 'Mito|Realtà', 'Il tacchino ne ha più o meno quanto il pollo. A far venire sonno è l’enorme pranzo delle feste.'],
    ['Dopo mangiato bisogna aspettare almeno un’ora, o tre come dicono le nonne, prima di fare il bagno.', 'Mito|Realtà', 'Non c’è nessuna prova che un pasto renda pericoloso nuotare.'],
    ['Leggere con poca luce rovina la vista.', 'Mito|Realtà', 'Può stancare gli occhi, ma non fa danni permanenti.'],
    ['Una gomma da masticare inghiottita resta nello stomaco per sette anni.', 'Mito|Realtà', 'Il corpo non riesce a digerirla, ma esce in pochi giorni come qualsiasi altra cosa.'],
    ['Il sangue è blu finché non incontra l’ossigeno.', 'Mito|Realtà', 'È sempre rosso, più scuro quando ha poco ossigeno. Le vene sembrano blu solo attraverso la pelle.'],
    ['Un grande spavento può far diventare bianchi i capelli in una notte.', 'Mito|Realtà', 'I capelli già cresciuti non possono cambiare colore. Lo stress però può far cadere quelli scuri, lasciando quelli grigi.'],
    ['Il caffè blocca la crescita dei bambini.', 'Mito|Realtà', 'Nessuno studio l’ha mai dimostrato, anche se troppa caffeina non fa bene ai bambini.'],
    ['Un bicchierino di alcol ti scalda quando fa freddo.', 'Mito|Realtà', 'Fa sentire calda la pelle, ma fa perdere calore al corpo più in fretta.'],
    ['Antonio Salieri avvelenò Mozart.', 'Mito|Realtà', 'Erano rivali, ma in modo amichevole. La storia nacque da voci di corridoio e da un’opera teatrale.'],
    ['Maria Antonietta disse: «Che mangino brioche».', 'Mito|Realtà', 'La frase compare negli scritti di Rousseau, quando lei era ancora una bambina in Austria.'],
    ['Il corpo di Walt Disney fu ibernato dopo la sua morte.', 'Mito|Realtà', 'Fu cremato nel 1966. La storia cominciò come voce anni dopo.'],
    ['Nerone suonava la cetra mentre Roma bruciava.', 'Mito|Realtà', 'Con ogni probabilità era lontano, ad Anzio, quando scoppiò l’incendio. Nella versione inglese suona il violino, che allora non esisteva nemmeno.'],
    ['Le tarme adulte si mangiano i vestiti.', 'Mito|Realtà', 'Il danno lo fanno le larve. Molte tarme adulte non mangiano affatto.'],
    ['Tutte le api muoiono dopo aver punto.', 'Mito|Realtà', 'Succede solo alle api operaie, e soprattutto quando pungono mammiferi, perché il pungiglione uncinato resta incastrato.'],
    ['Il qua qua di un’anatra non fa eco.', 'Mito|Realtà', 'La fa. L’eco è solo difficile da sentire, perché il verso si spegne lentamente.'],
    ['Se tagli a metà un lombrico, ottieni due lombrichi.', 'Mito|Realtà', 'A volte la parte con la testa sopravvive e si rifà la coda. L’altra metà muore.'],
    ['Il microonde cuoce il cibo dall’interno verso l’esterno.', 'Mito|Realtà', 'Scalda i primi centimetri esterni. Poi il calore si diffonde verso l’interno.'],
    ['Rosolare la carne a fuoco vivo sigilla i succhi all’interno.', 'Mito|Realtà', 'La carne rosolata perde più o meno gli stessi succhi. Ha solo un sapore migliore.'],
    ['Aggiungere sale all’acqua della pentola la fa bollire molto prima.', 'Mito|Realtà', 'Un pizzico di sale alza di pochissimo il punto di ebollizione. Serve per il sapore.'],
    ['Paul Revere cavalcò tutta la notte gridando «Arrivano gli inglesi!».', 'Mito|Realtà', 'La missione era segreta, e quasi tutti i coloni si consideravano ancora britannici.'],
    ['Le persone giustiziate nei processi alle streghe di Salem furono bruciate sul rogo.', 'Mito|Realtà', 'Diciannove furono impiccate, e un uomo fu schiacciato con delle pietre.'],
    ['Frankenstein è il nome del mostro nel romanzo di Mary Shelley.', 'Mito|Realtà', 'Victor Frankenstein è lo scienziato. La sua creatura non ha un nome.'],
    ['In Casablanca, Humphrey Bogart dice «Play it again, Sam», «Suonala ancora, Sam».', 'Mito|Realtà', 'Le battute vere sono «Play it, Sam» e «Play it!».'],
    ['Nello Star Trek originale il capitano Kirk dice «Beam me up, Scotty», «Teletrasporto, Scotty».', 'Mito|Realtà', 'Mai con queste parole esatte.'],
    ['Tutti hanno bisogno di bere esattamente otto bicchieri d’acqua al giorno, oltre al cibo.', 'Mito|Realtà', 'Il fabbisogno cambia, e contano anche il cibo, il tè e le altre bevande.'],
    ['Uscire con i capelli bagnati fa venire il raffreddore.', 'Mito|Realtà', 'Il raffreddore viene dai virus. D’inverno si diffonde di più perché si sta tutti ammassati al chiuso.'],
    ['Quando starnutisci il cuore si ferma per un attimo.', 'Mito|Realtà', 'Il cambio di pressione può alterarne un po’ il ritmo, ma il cuore continua a battere.'],
    ['I gemelli identici hanno impronte digitali identiche.', 'Mito|Realtà', 'Le impronte si formano anche per minuscole differenze nell’utero, quindi perfino i gemelli le hanno diverse.'],
    ['I topi amano il formaggio più di qualsiasi altro cibo.', 'Mito|Realtà', 'Preferiscono cereali, semi e cose dolci. Un formaggio dall’odore forte può perfino tenerli lontani.'],
    ['I conigli dovrebbero mangiare tante carote.', 'Mito|Realtà', 'Le carote sono dolcetti pieni di zucchero. I conigli hanno bisogno soprattutto di fieno ed erba.'],
    ['La luna piena fa comportare la gente in modo strano.', 'Mito|Realtà', 'Gli studi sui dati di ospedali e polizia non trovano nessun effetto reale.'],
    ['I meteoriti di solito sono roventi quando toccano terra.', 'Mito|Realtà', 'Nell’aria fonde solo lo strato esterno. Quasi tutti arrivano tiepidi o perfino freddi.'],
    ['La vergine di Norimberga era un comune strumento di tortura medievale.', 'Mito|Realtà', 'Quasi tutti gli esemplari famosi furono assemblati nell’Ottocento, forse come falsi per i musei.'],
    ['I combattimenti tra gladiatori romani finivano sempre con la morte.', 'Mito|Realtà', 'Addestrare un gladiatore costava caro, e molti incontri finivano quando uno dei due si arrendeva.'],
    ['I romani avevano i «vomitori» per vomitare durante i banchetti.', 'Mito|Realtà', 'Il vomitorium era un passaggio che permetteva alla folla di «riversarsi» fuori da uno stadio.'],
    ['Le antiche statue greche dovevano essere di semplice marmo bianco.', 'Mito|Realtà', 'Molte erano dipinte a colori vivaci. I colori sono sbiaditi nei secoli.'],
    ['Nel Medioevo quasi tutti gli adulti morivano intorno ai 30 anni.', 'Mito|Realtà', 'La media era abbassata dalle morti dei bambini. Molti adulti vivevano fino a 60 anni e oltre.'],
    ['Benjamin Franklin propose ufficialmente il tacchino come uccello nazionale degli Stati Uniti.', 'Mito|Realtà', 'Scherzò soltanto, in una lettera alla figlia, che il tacchino era un uccello più rispettabile dell’aquila.'],
    ['Le gomme dell’auto ti proteggono dai fulmini.', 'Mito|Realtà', 'È la carrozzeria di metallo a portare la corrente intorno a te fino a terra. Le decappottabili non sono sicure.'],
    ['Se smetti di allenarti, i muscoli si trasformano in grasso.', 'Mito|Realtà', 'Sono tessuti diversi. Il muscolo può ridursi mentre il grasso aumenta, e sembra uno scambio.'],
    ['I ninja si vestivano di nero dalla testa ai piedi.', 'Mito|Realtà', 'Quel look viene dal teatro giapponese, dove i macchinisti vestiti di nero dovevano essere «invisibili».'],
    ['Einstein vinse il Nobel per la teoria della relatività.', 'Mito|Realtà', 'Lo vinse per aver spiegato l’effetto fotoelettrico, che ha contribuito a rendere possibili i pannelli solari.'],
    ['Thomas Crapper inventò il water con lo sciacquone.', 'Mito|Realtà', 'John Harington ne costruì uno negli anni Novanta del Cinquecento. Crapper era un idraulico di successo che lo migliorò.'],
    ['L’ora legale fu introdotta per aiutare i contadini.', 'Mito|Realtà', 'I contadini erano quasi tutti contrari. La Germania la introdusse nel 1916 per risparmiare carburante in tempo di guerra.'],
    ['Braccio di Ferro mangia spinaci perché una virgola messa male li fece sembrare pieni di ferro.', 'Mito|Realtà', 'La storia della virgola è a sua volta un mito. Il creatore di Braccio di Ferro scelse gli spinaci per la vitamina A.'],
    ['Il cibo piccante provoca l’ulcera allo stomaco.', 'Mito|Realtà', 'Quasi tutte le ulcere sono causate da un batterio, l’Helicobacter pylori, o da alcuni antidolorifici.'],
    ['Il cuore sta nella parte sinistra del petto.', 'Mito|Realtà', 'Sta quasi al centro, dietro lo sterno, con la punta rivolta a sinistra.'],
    ['Tutti i pinguini vivono nell’emisfero australe.', 'Mito|Realtà', 'I pinguini delle Galápagos vivono sull’Equatore, e alcuni lo superano appena verso nord.'],
    ['Tutti gli squali devono continuare a nuotare, altrimenti muoiono.', 'Mito|Realtà', 'Molti, come lo squalo nutrice, possono riposare sul fondale pompando acqua sulle branchie.'],
    ['Le noci di cocco che cadono uccidono circa 150 persone all’anno.', 'Mito|Realtà', 'Il numero non ha nessuna fonte vera. Lo diffuse il comunicato stampa di un’assicurazione di viaggio.'],
    ['Non si deve mai svegliare un sonnambulo.', 'Mito|Realtà', 'Non è pericoloso, anche se può essere confuso. La cosa migliore è riaccompagnarlo con delicatezza a letto.'],
    ['Gli elefanti bevono con la proboscide come con una cannuccia.', 'Mito|Realtà', 'Aspirano l’acqua fino a metà della proboscide, poi se la spruzzano in bocca.'],
    ['I colibrì migrano viaggiando sulla schiena delle oche.', 'Mito|Realtà', 'Volano da soli, e alcuni attraversano il Golfo del Messico senza sosta.'],
    ['I serpenti si slogano la mascella per inghiottire prede grosse.', 'Mito|Realtà', 'Le due metà della mandibola sono unite da un tessuto elastico, così la bocca si spalanca senza staccarsi.'],
    ['L’acqua pura conduce male l’elettricità.', 'Realtà|Mito', 'Sono i sali e i minerali disciolti nell’acqua normale a trasportare la corrente.'],
    ['Alcuni gatti sono allergici agli esseri umani.', 'Realtà|Mito', 'È raro, ma i gatti possono reagire alla forfora umana.'],
    ['Mangiare tantissime carote può far diventare la pelle arancione.', 'Realtà|Mito', 'Troppo betacarotene dà alla pelle una sfumatura giallo-arancio, di solito sui palmi. È innocuo.'],
    ['Nel New England coloniale l’aragosta era considerata cibo da poveri.', 'Realtà|Mito', 'Era così abbondante che la si dava da mangiare ai prigionieri e ai servi.'],
    ['Non si riesce a canticchiare a bocca chiusa tappandosi il naso.', 'Realtà|Mito', 'Canticchiare manda l’aria fuori dal naso. Se lo blocchi, il suono si ferma in pochi secondi.'],
    ['Orsi polari e pinguini non si incontrano mai in natura.', 'Realtà|Mito', 'Gli orsi polari vivono nell’Artico, e i pinguini quasi solo nell’emisfero australe.'],
    ['La Grande Piramide è stata la costruzione umana più alta per circa 3.800 anni.', 'Realtà|Mito', 'Perse il titolo, intorno al 1311, a favore della guglia della cattedrale di Lincoln, in Inghilterra.'],
    ['In Svizzera è vietato tenere un solo porcellino d’India.', 'Realtà|Mito', 'Sono animali sociali, quindi la legge dice che hanno bisogno di compagnia.'],
    ['Il cervello in sé non sente dolore.', 'Realtà|Mito', 'Non ha recettori del dolore, quindi alcune operazioni al cervello si fanno con il paziente sveglio.'],
    ['Un «momento» un tempo era un’unità di tempo di circa 90 secondi.', 'Realtà|Mito', 'Gli autori medievali dividevano l’ora in 40 momenti.'],
    ['Alcune tartarughe possono vivere più di 150 anni.', 'Realtà|Mito', 'Jonathan, una tartaruga gigante di Sant’Elena, è nato intorno al 1832.'],
    ['Gli antichi egizi curavano le infezioni con il pane ammuffito.', 'Realtà|Mito', 'Alcune muffe producono antibiotici naturali, molto prima che si scoprisse la penicillina.'],
    ['Una moneta lanciata ha leggermente più probabilità di cadere sul lato da cui è partita.', 'Realtà|Mito', 'Uno studio del 2023 su oltre 350.000 lanci ha scoperto che succede circa il 50,8% delle volte.'],
    ['Non sono mai stati trovati due fiocchi di neve uguali.', 'Mito|Realtà', 'Nel 1988 una scienziata trovò una coppia identica di cristalli semplici durante una tempesta nel Wisconsin. Quelli complessi sono quasi certamente tutti unici.'],
    ['Il ghiaccio è ufficialmente un minerale.', 'Realtà|Mito', 'I geologi lo contano: è naturale, solido e cristallino. L’acqua liquida no.'],
    ['Il nucleo interno della Terra è caldo più o meno come la superficie del Sole.', 'Realtà|Mito', 'Circa 5.200 °C, sotto una pressione così grande che il ferro resta solido.'],
    ['Michael Jordan fu escluso dalla squadra di basket del suo liceo.', 'Mito|Realtà', 'Al secondo anno fu messo nella squadra giovanile invece che nella prima. Però usò lo sgarbo come motivazione.'],
    ['Gli squali non si ammalano mai di cancro.', 'Mito|Realtà', 'Sono stati trovati tumori in molte specie di squali. Il mito ha alimentato un commercio dannoso di pillole di cartilagine di squalo.'],
    ['Il gruppo sanguigno determina il carattere.', 'Mito|Realtà', 'L’idea è popolarissima in Giappone e in Corea del Sud, ma gli studi non trovano nessun legame reale.'],
  ],
};
